// ---- 前世记忆页
//  每页 8 行，行高 62（含 8px 间隙）。8 行底边 606，下面 636 摆按钮，够放。
Gdiplus::Rect CardMemRowRect(int i) { return Gdiplus::Rect(150, 118 + i * 62, 900, 54); }
Gdiplus::Rect CardMemBtnRect(int i) { return Gdiplus::Rect(150 + i * 132, 636, 120, 46); }
Gdiplus::Rect CardMemSaveRect()     { return Gdiplus::Rect(930, 636, 150, 46); }
const int kMemRowsPerPage = 8;
int CardMemBtnHit(int i)  { return -40 - i; }   // -40上一页 -41下一页 -42新增 -43删除
int CardMemSaveHit()      { return -44; }

// ---- 人设全文页布局
//  上面两个 tab 切换"怎么说 / 示例台词"，下面一整块编辑区。
//  人设是大段文字，行高和宽度都要比"一行一条"的人设页宽裕。
Gdiplus::Rect CardPtTabRect(int i)  { return Gdiplus::Rect(150 + i * 200, 108, 184, 46); }
Gdiplus::Rect CardPtBoxRect()       { return Gdiplus::Rect(150, 168, 980, 420); }
Gdiplus::Rect CardPtSaveRect()      { return Gdiplus::Rect(150, 606, 190, 52); }
int CardPtTabHit(int i)  { return -50 - i; }    // -50 说话方式 -51 示例台词
int CardPtSaveHit()      { return -53; }
int CardPtBoxHit()       { return -54; }        // 点编辑区 = 开始编辑
int CardPtEntryHit()     { return -55; }        // 人设页上的入口按钮

// ---- 头像页布局
// 左边一块大的"当前头像"预览，右边 3×2 候选网格，底下一排操作按钮。
const int kAvCols = 3, kAvRows = 2;
const int kAvCW = 220, kAvCH = 176, kAvGX = 20, kAvGY = 14;
const int kAvX0 = 440, kAvY0 = 150;

Gdiplus::Rect CardAvatarPreviewRect() { return Gdiplus::Rect(100, 170, 280, 300); }

Gdiplus::Rect CardAvGridRect(int idx) {
    int c = idx % kAvCols, r = idx / kAvCols;
    return Gdiplus::Rect(kAvX0 + c * (kAvCW + kAvGX),
                         kAvY0 + r * (kAvCH + kAvGY), kAvCW, kAvCH);
}
// 按钮：0 = 用这张当头像，1 = 清除配置（退回默认造型）
Gdiplus::Rect CardAvBtnRect(int i) { return Gdiplus::Rect(440 + i * 232, 546, 212, 52); }
int CardAvBtnHit(int i) { return -30 - i; }
// 剧本包 —— assets\syllabus 下每份一个，点选切换 / 删除 / 打开目录
//
// 为什么剧本要独立成"包"
// 角色决定"谁来教"，剧本决定"教什么"。这两件事本来就是正交的：
// 同一个人可以教 C 语言也可以教数据结构，同一套课也能换个人来讲。
// 原来剧本焊死在 assets\syllabus.ini 一个路径上，换角色不换课，
// "角色包可更换"就只做了一半。
//
// 为什么不在界面里新建剧本
// 写大纲是改几十行 ini（章节目标、题目、选项），本来就得在编辑器里写。
// 界面只负责"选哪一份、删哪一份、目录在哪"，新建交给文件系统
// 真要能新建，做出来也只是个"复制当前这份再改"的按钮，用处有限。
//
// 删除为什么分两种
// 目录式包（assets\syllabus\<名字>\）整目录删，因为里面可能有备注、
// 素材、README 之类跟这份大纲配套的东西；单文件包只删那一个 .ini。
// 旧的那份 assets\syllabus.ini 不给删——删了就一份都不剩，
// dirMode 会静默退回老剧本模式，玩家只会觉得"游戏突然变味了"。
const int kSyX0 = 120, kSyY0 = 132, kSyW = 1040;
const int kSyRowH = 82, kSyGap = 10, kSyRows = 5;

Gdiplus::Rect SyRowRect(int i) {
    return Gdiplus::Rect(kSyX0, kSyY0 + i * (kSyRowH + kSyGap), kSyW, kSyRowH);
}
// 按钮：0 = 编辑章节，1 = 打开目录，2 = 删除
//
// 「编辑章节」排在最左它是这个页面最常用的动作
// 作者点进剧本页多半就是为了改内容，而不是为了删。
// 删除放最右，且要二次确认，误触成本最高的放最远。
Gdiplus::Rect SyBtnRect(int i) { return Gdiplus::Rect(400 + i * 240, 620, 220, 52); }
int SyBtnHit(int i) { return -30 - i; }

static void DrawSyllabus(Graphics& g, App& a) {
    DrawBackdropBack(g, a);
    DrawTitle(g, L"剧本", 24);

    const std::vector<SyllabusPack>& ps = a.syllabusPacks;
    if (ps.empty()) {
        Gdiplus::Font f(L"Microsoft YaHei", 17);
        Gdiplus::Rect r(200, 300, 880, 60);
        Center(g, L"（没有找到剧本——往 assets\\syllabus\\ 下放一个目录，里面放 syllabus.ini）",
               f, r, kTextDim);
        return;
    }

    int perPage = kSyRows;
    int start = a.ui.scroll * perPage;
    for (int i = 0; i < perPage; ++i) {
        int idx = start + i;
        if (idx >= (int)ps.size()) break;
        const SyllabusPack& p = ps[(size_t)idx];

        bool cur  = (p.id == a.syllabusId);
        bool on   = (a.ui.syPick == idx) || (a.ui.hover == idx);
        Gdiplus::Rect r = SyRowRect(i);

        // 当前这份用主题色描边 + 左侧竖条，一眼看出"正在用的是哪个"。
        RR(g, r, 12, on ? kCardHot : kCard,
           cur ? kAccent : (on ? Color::MakeARGB(160, 120, 115, 140)
                               : Color::MakeARGB(110, 90, 90, 110)),
           cur ? 2.5f : 1.2f);
        if (cur) {
            Gdiplus::SolidBrush ab(kAccent);
            g.FillRectangle(&ab, r.X + 8, r.Y + 14, 5, r.Height - 28);
        }

        // 第一行：标题 + 「当前」角标
        std::wstring name = p.title.empty() ? p.id : p.title;
        Gdiplus::Font fn(L"Microsoft YaHei", 19, Gdiplus::FontStyleBold);
        Gdiplus::Rect nr(r.X + 26, r.Y + 12, r.Width - 200, 32);
        LeftIn(g, name, fn, nr, cur ? kText : kText);

        if (cur) {
            Gdiplus::Font fc(L"Microsoft YaHei", 13, Gdiplus::FontStyleBold);
            Gdiplus::Rect cr(r.X + r.Width - 150, r.Y + 16, 120, 26);
            Center(g, L"当前使用", fc, cr, kAccent);
        }
        //
        // ---- 「通用」/「角色B特化」标签
        //
        // 选了特化剧本之后开始游戏就只能选那个角色，所以这个标签
        // 必须在点之前就能看见——否则玩家选完了才发现角色被锁，
        // 只会以为是程序不让他选人。
        {
            const bool spec = !p.charId.empty();
            std::wstring tag = spec ? (p.charId + L"特化") : L"通用";
            Gdiplus::Font ft(L"Microsoft YaHei", 13, Gdiplus::FontStyleBold);
            Gdiplus::Rect tr(r.X + r.Width - 300, r.Y + 16, 140, 26);
            Center(g, tag, ft, tr,
                   spec ? Color::MakeARGB(255, 235, 170, 90) : kTextDim);
        }

        // 第二行：目录名 + 章数。目录名才是"文件里叫它什么"，
        // 去资源管理器里找的时候靠的是这个名字，不是标题。
        Gdiplus::Font fs(L"Microsoft YaHei", 13);
        std::wstring sub = L"目录名：" + p.id;
        if (p.legacy) sub += L"（旧的单文件，不可删除）";
        else if (p.singleFile) sub += L"（单文件）";
        Gdiplus::Rect sr(r.X + 26, r.Y + 48, 620, 24);
        LeftIn(g, sub, fs, sr, kTextDim);

        Gdiplus::Font fc2(L"Microsoft YaHei", 13);
        Gdiplus::Rect cr2(r.X + r.Width - 220, r.Y + 48, 190, 24);
        // 剧情剧本的"章"叫"幕"——一字之差，但作者对着界面数章节时
        // 看到"6 章"会以为自己点错了剧本。
        RightIn(g, WFromInt(p.chapters) + (p.charId.empty() ? L" 章" : L" 幕"),
                fc2, cr2, kTextDim);
    }

    // ---- 按钮
    int pick = a.ui.syPick;
    bool hasPick = (pick >= 0 && pick < (int)ps.size());
    bool canDel  = hasPick && !ps[(size_t)pick].legacy;

    for (int i = 0; i < 3; ++i) {
        Gdiplus::Rect r = SyBtnRect(i);
        // 编辑和打开目录也依赖"选中了哪一份"，没选中就灰着。
        bool grey = (i == 2 && !canDel) || (i != 2 && !hasPick);
        RR(g, r, 10, grey ? kLocked : (a.ui.hover == -30 - i ? kCardHot : kCard),
           grey ? Color::MakeARGB(80, 90, 90, 110) : kAccent, 1.5f);
        // 二次确认时按钮文案变成"再点一次删除"，比弹对话框轻。
        // 弹窗要处理焦点和层序，这里只是个列表，不值得。
        std::wstring t;
        if (i == 0)      t = L"编辑章节";
        else if (i == 1) t = L"打开剧本目录";
        else t = a.ui.syConfirmDel ? L"再点一次确认删除" : L"删除这个剧本";
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, t, f, r, grey ? kTextDim : kText);
    }

    Gdiplus::Font fh(L"Microsoft YaHei", 14);
    // 596 会跟下面的按钮（620 起）压上 2 像素，实测过的，别改回去
    Gdiplus::Rect hr(200, 586, 880, 26);
    Center(g, L"点一下选中，再点一下切换 —— 换的是【教什么】，跟角色无关", fh, hr, kTextDim);
}

static int SyllabusHitTest(const App& a, int x, int y) {
    auto inRect = [&](const Gdiplus::Rect& r) {
        return x >= r.X && x < r.X + r.Width && y >= r.Y && y < r.Y + r.Height;
    };

    for (int i = 0; i < 3; ++i)
        if (inRect(SyBtnRect(i))) return SyBtnHit(i);

    const std::vector<SyllabusPack>& ps = a.syllabusPacks;
    int start = a.ui.scroll * kSyRows;
    for (int i = 0; i < kSyRows; ++i) {
        int idx = start + i;
        if (idx >= (int)ps.size()) break;
        if (inRect(SyRowRect(i))) return idx;
    }
    return -1;
}

// 删除选中的剧本。删完自动落到剩下第一份。
static bool SyDelete(App& a) {
    int pick = a.ui.syPick;
    if (pick < 0 || pick >= (int)a.syllabusPacks.size()) return false;
    SyllabusPack p = a.syllabusPacks[(size_t)pick];
    if (p.legacy) return false;              // 旧的单文件不给删
    if (!a.ui.syConfirmDel) { a.ui.syConfirmDel = true; return false; }
    a.ui.syConfirmDel = false;

    bool done = p.singleFile ? (DeleteFileW(p.path.c_str()) != FALSE)
                             : RemoveDirRecursive(p.dir);
    if (!done) {
        // 删不掉大多是被资源管理器/编辑器占用着。给个明确说法，
        // 而不是默默回到列表——玩家会以为按钮坏了。
        UiTip(a, L"删不掉：文件被别的程序占用着，先关掉再试", 4);
        return false;
    }

    a.ui.syPick = -1;
    a.ui.scroll = 0;
    // 删的正好是正在用的那份时，syllabusId 已经不存在了，
    // LoadSyllabus 会自动落到第一份——这里清一下只是让日志好看。
    if (p.id == a.syllabusId) a.syllabusId.clear();
    LoadSyllabus();
    IniSetStr(a.configPath, L"Game", L"Syllabus", a.syllabusId);
    AppLog(L"已删除剧本：%s", p.id.c_str());
    return true;
}
// 剧本编辑 —— 章节增删 + 每章的标题/目标/题干/选项/答案
//
// 为什么剧本必须能在游戏里编
// 〔章数〕
// 于是"这游戏只能有 5 章"——想做 12 章要改代码重新编译，
// 想做 3 章的小品，槽位空着但"最后一章"仍按数组走。
// 现在章数由 ini 里写了几个 [N] 决定，1 章也行，100 章也行。
// 这一页就是它的界面：加一章 = 加一个段，删一章 = 段整体前移。
//
// 编辑的是副本，不是正在玩的那一份
// a.syllabus（Director 里那份）是正在玩的剧本。编辑页改的是 sylEd
// 一份独立加载的副本。直接改 a.syllabus 会出这种事：
// 副本改完点保存才写盘；写盘后如果它就是当前在用的那份，重新加载一次。
//
// 布局左栏章节列表，右栏"选中那章的字段"。
// 右栏做成一条扁平的字段列表（而不是每字段一个固定位置），
// 是因为选项数量是变的（3 个也行 6 个也行），写死 4 个位置就得留空行，
// 而"空行"跟"这一项没配"在界面上长得一模一样，看不出来。
const int kSylEdChX = 90,  kSylEdChY = 130, kSylEdChW = 330;
const int kSylEdChH = 46,  kSylEdChGap = 8, kSylEdChRows = 8;
const int kSylEdFdX = 452, kSylEdFdY = 130, kSylEdFdW = 738;
const int kSylEdFdH = 46,  kSylEdFdGap = 8, kSylEdFdRows = 8;

Gdiplus::Rect SylEdChRect(int i) {
    return Gdiplus::Rect(kSylEdChX, kSylEdChY + i * (kSylEdChH + kSylEdChGap),
                         kSylEdChW, kSylEdChH);
}
Gdiplus::Rect SylEdFdRect(int i) {
    return Gdiplus::Rect(kSylEdFdX, kSylEdFdY + i * (kSylEdFdH + kSylEdFdGap),
                         kSylEdFdW, kSylEdFdH);
}
// 左栏底部的四个按钮：翻页 + 增删章
Gdiplus::Rect SylEdChBtnRect(int i) {
    return Gdiplus::Rect(kSylEdChX + i * 84, kSylEdChY + kSylEdChRows * (kSylEdChH + kSylEdChGap) + 12, 76, 44);
}
// 右下三个按钮：加选项 / 删选项 / 保存
Gdiplus::Rect SylEdBtnRect(int i) {
    return Gdiplus::Rect(560 + i * 200, 622, 180, 52);
}
// 命中码：章节行 0..n-1；字段行 100..100+n-1；按钮 -60..-64
int SylEdChBtnHit(int i) { return -60 - i; }
int SylEdBtnHit(int i)   { return -70 - i; }

// 右栏一个可编辑的字段。
struct SylEdField {
    std::wstring cap;      // 界面上显示的名字
    std::wstring key;      // ini 里的键名（选项这一行是 Opt1/Opt2…，要连号）
    std::wstring val;      // 当前值
    bool         num = false;   // true = 这一项是数字（答案 / 次数），空着当 0
    bool         fixed = false; // true = 删不掉（章节名、教学目标必须有）
};

static std::vector<SylEdField> SylEdFields(const App& a) {
    std::vector<SylEdField> v;
    if (a.ui.sylEdCh < 0 || a.ui.sylEdCh >= (int)a.sylEd.chapters.size()) return v;
    const SyllabusChapter& c = a.sylEd.chapters[(size_t)a.ui.sylEdCh];

    auto add = [&](const wchar_t* cap, const wchar_t* key, const std::wstring& val,
                   bool num = false, bool fixed = false) {
        SylEdField f; f.cap = cap; f.key = key; f.val = val; f.num = num; f.fixed = fixed;
        v.push_back(f);
    };
    add(L"章节名",   L"Name",      c.name,  false, true);
    add(L"教学目标", L"Goal",      c.goal,  false, true);
    add(L"背景",     L"Bg",        c.bg);
    add(L"开场曲",   L"Bgm",       c.bgm);
    add(L"题目标题", L"TaskTitle", c.task.title);
    add(L"题干",     L"Stmt",      c.task.stmt);
    for (size_t i = 0; i < c.task.opts.size(); ++i)
        add((L"选项" + WFromInt((int)i + 1)).c_str(),
            (L"Opt" + WFromInt((int)i + 1)).c_str(), c.task.opts[i]);
    add(L"正确答案", L"Answer", c.task.answer > 0 ? WFromInt(c.task.answer) : L"", true);
    add(L"答错几次给提示", L"Tries", c.task.tries > 0 ? WFromInt(c.task.tries) : L"", true);
    add(L"提示内容", L"Hint", c.task.hint);
    return v;
}

// 把界面上的改动收进 sylEd（还没写盘）。
// 编辑框里的内容在"保存 / 换章 / 换字段"时才收，不是每帧收——
// 每帧收的话，打字打到一半的另一个字段会被上一次的值覆盖。
static void SylEdCommitField(App& a) {
    std::vector<SylEdField> v = SylEdFields(a);
    int r = a.ui.sylEdRow;
    if (r < 0 || r >= (int)v.size()) return;
    if (!a.hEdit) return;
    // 【不能写死缓冲长度】题干和选项是一整段代码，几 KB 很正常，
    // 固定 1024 会把后半截静默吃掉，而界面上完全看不出来。
    int n = GetWindowTextLengthW(a.hEdit);
    std::wstring s((size_t)(n > 0 ? n : 0), L'\0');
    if (n > 0) GetWindowTextW(a.hEdit, &s[0], n + 1);
    s = Trim(s);
    //
    // ---- 这里原来只查了 r（编辑行），没查 sylEdCh（选中的章）
    // 删掉一章之后 sylEdCh 可能还停在那个已经不存在的下标上，
    // 此时在编辑框里回车就是 vector subscript out of range。
    if (a.ui.sylEdCh < 0 || a.ui.sylEdCh >= (int)a.sylEd.chapters.size()) return;
    SyllabusChapter& c = a.sylEd.chapters[(size_t)a.ui.sylEdCh];
    const std::wstring& key = v[(size_t)r].key;
    // 按 key 分发。这里不按 cap 判——cap 是给人看的，改个措辞就废了。
    if      (key == L"Name")      c.name = s;
    else if (key == L"Goal")      c.goal = s;
    else if (key == L"Bg")        c.bg = s;
    else if (key == L"Bgm")       c.bgm = s;
    // 【Outfit 分支已移除】服装机制已移除，界面上不再有这一行，
    // 这里也就没有对应的 key 可以进来。
    else if (key == L"TaskTitle") c.task.title = s;
    else if (key == L"Stmt")      c.task.stmt = s;
    else if (key == L"Answer") { int n = 0; ParseIntFromStr(s, &n); c.task.answer = n; }
    else if (key == L"Tries")  { int n = 0; ParseIntFromStr(s, &n); c.task.tries  = n; }
    else if (key == L"Hint")      c.task.hint = s;
    else if (key.rfind(L"Opt", 0) == 0) {
        int idx = 0;
        // 走 ParseIntFromStr 而不是 _wtoi：它认得前后带空格、带引号的数字，
        // 而且不依赖 Windows 专属函数。
        ParseIntFromStr(key.substr(3), &idx);
        --idx;
        if (idx >= 0 && idx < (int)c.task.opts.size()) c.task.opts[(size_t)idx] = s;
    }
}
// 两条路径是不是同一个文件。
// 不能直接比字符串：一份可能来自扫描（拼出来的），一份来自 config（存进去的），
// 大小写和斜杠方向都可能不同，比出来不相等就会漏掉那次重新加载
// 于是"保存成功"但游戏里跑的还是旧大纲。
static bool PathEq(const std::wstring& p, const std::wstring& q) {
    if (p.empty() || q.empty()) return false;
    std::wstring x = p, y = q;
    for (size_t i = 0; i < x.size(); ++i) {
        if (x[i] == L'/') x[i] = L'\\';
        else if (x[i] >= L'A' && x[i] <= L'Z') x[i] = (wchar_t)(x[i] + 32);
    }
    for (size_t i = 0; i < y.size(); ++i) {
        if (y[i] == L'/') y[i] = L'\\';
        else if (y[i] >= L'A' && y[i] <= L'Z') y[i] = (wchar_t)(y[i] + 32);
    }
    // 结尾的斜杠也抹掉：目录式和单文件式拼出来的可能差一个
    while (!x.empty() && x.back() == L'\\') x.pop_back();
    while (!y.empty() && y.back() == L'\\') y.pop_back();
    return x == y;
}

// 写盘。
static bool SylEdSave(App& a) {
    const std::wstring& path = a.sylEdPath;
    if (path.empty()) { UiTip(a, L"没有正在编辑的剧本", 3); return false; }
    if (a.sylEd.chapters.empty()) { UiTip(a, L"至少得有一章", 3); return false; }

    // 先在内存里校验一遍——写一半再报错更糟：
    // 文件已经改了但游戏读不了，玩家看到的是"剧本莫名其妙坏了"。
    for (size_t i = 0; i < a.sylEd.chapters.size(); ++i) {
        const SyllabusChapter& c = a.sylEd.chapters[i];
        if (c.name.empty()) { UiTip(a, L"第 " + WFromInt((int)i + 1) + L" 章没写章节名", 4); return false; }
        if (c.goal.empty()) { UiTip(a, L"第 " + WFromInt((int)i + 1) + L" 章没写教学目标", 4); return false; }
        if (!c.task.stmt.empty()) {
            if (c.task.opts.size() < 2) {
                UiTip(a, L"第 " + WFromInt((int)i + 1) + L" 章写了题干却只有 "
                         + WFromInt((int)c.task.opts.size()) + L" 个选项（至少 2 个）", 4);
                return false;
            }
            if (c.task.answer < 1 || c.task.answer > (int)c.task.opts.size()) {
                UiTip(a, L"第 " + WFromInt((int)i + 1) + L" 章的正确答案要在 1~"
                         + WFromInt((int)c.task.opts.size()) + L" 之间", 4);
                return false;
            }
        }
    }

    IniInvalidate(path);
    IniSetStr(path, L"Course", L"Title", a.sylEd.title);
    IniSetStr(path, L"Course", L"Chapters", WFromInt((int)a.sylEd.chapters.size()));
    //
    // ---- 课程名和两张词表必须原样写回
    //
    // 编辑页目前只能改章节，改不到这三样，但它们在文件里
    // 不写回就等于保存一次把整门课抹掉：下次读进来 CodeWords 为空，
    // 退回内置的 C 语言那套，作者的 Python 词表凭空消失，
    // 而界面上看不出任何变化（章数没变、标题没变）。
    IniSetStr(path, L"Course", L"Subject", a.sylEd.subject);
    IniSetStr(path, L"Course", L"CodeWords",  EscapeIni(JoinLines(a.sylEd.codeWords)));
    IniSetStr(path, L"Course", L"TeachWords", EscapeIni(JoinLines(a.sylEd.teachWords)));

    for (size_t i = 0; i < a.sylEd.chapters.size(); ++i) {
        const SyllabusChapter& c = a.sylEd.chapters[i];
        std::wstring sec = WFromInt((int)i + 1);
        IniSetStr(path, sec.c_str(), L"Name", c.name);
        IniSetStr(path, sec.c_str(), L"Goal", EscapeIni(c.goal));
        IniSetStr(path, sec.c_str(), L"Bg", c.bg);
        IniSetStr(path, sec.c_str(), L"Bgm", c.bgm);
        // 【服装字段不再写盘】服装机制已移除。
        // 原来这里无条件写一行 Outfit=（空），于是每份剧本的每章都会
        // 多出一行没用的配置。老剧本里已有的 Outfit 行不用管：
        // 不读它，留着也无害。
        IniSetStr(path, sec.c_str(), L"TaskTitle", c.task.title);
        IniSetStr(path, sec.c_str(), L"Stmt", EscapeIni(c.task.stmt));
        IniSetStr(path, sec.c_str(), L"Hint", EscapeIni(c.task.hint));
        IniSetStr(path, sec.c_str(), L"Tries", WFromInt(c.task.tries));
        IniSetStr(path, sec.c_str(), L"Answer", WFromInt(c.task.answer));
        //
        // 选项必须先删多余的再写
        // Opt 是"读空即停"的：把 4 个减到 3 个时只改前 3 个不够，
        // 留下来的 Opt4 会让下一次读到的还是 4 个
        // 界面上明明删掉了，加载回来又冒出来。所以按最大条数先清一遍。
        for (int o = 1; o <= 6; ++o) {
            std::wstring k = L"Opt" + WFromInt(o);
            if (o <= (int)c.task.opts.size()) IniSetStr(path, sec.c_str(), k.c_str(),
                                                        EscapeIni(c.task.opts[(size_t)(o - 1)]));
            else IniDelKey(path, sec.c_str(), k.c_str());
        }
    }

    // 删掉多出来的旧段。原来是 5 章、现在改成 3 章时，[4] [5] 还躺在文件里——
    // Chapters 已经写成 3 了，那两段不会被读，但作者打开文件会以为还在，
    // 再改一次就改到了幽灵章上。所以必须真的删。
    for (int i = (int)a.sylEd.chapters.size() + 1; i <= (int)a.sylEd.chapters.size() + 64; ++i) {
        std::wstring sec = WFromInt(i);
        std::wstring probe = Sec(path, sec, L"Name");
        if (probe.empty()) break;                 // 后面没有了
        IniDelSec(path, sec);
    }
    // 改的正好是正在用的那份 -> 重新加载，让改动立刻生效。
    // 不重新加载的话，界面提示"已保存"而游戏里还在跑旧大纲，
    //
    // 走 LoadSyllabus，不要直接改 a.dir 里那份大纲
    // 重新加载要同时刷新 packs / id / dirSyllabus / Director 四处，
    // 自己赋值只改得了一处，漏掉的那些会在下一局又冒出来旧的。
    IniInvalidate(path);
    if (PathEq(path, a.syllabusPath)) {
        bool ok = LoadSyllabus();
        UiTip(a, ok ? L"已保存，并重新加载了当前剧本"
                    : L"已保存，但重新加载失败（见日志）", 4);
    } else {
        UiTip(a, L"已保存到 " + path, 4);
    }
    AppLog(L"剧本已保存：%s（%d 章）", path.c_str(), (int)a.sylEd.chapters.size());
    return true;
}

static void DrawSyllabusEdit(Graphics& g, App& a) {
    DrawBackdropBack(g, a);
    std::wstring tt = L"剧本编辑";
    if (!a.sylEd.title.empty()) tt += L" · " + a.sylEd.title;
    DrawTitle(g, tt, 22);

    const int nCh = (int)a.sylEd.chapters.size();
    if (nCh == 0) {
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Gdiplus::Rect r(200, 300, 880, 50);
        Center(g, L"（这个剧本一章都没有——先点「新增章」）", f, r, kTextDim);
        // 一章都没有时也要能加章，所以按钮照样画
    }

    // ---- 左栏：章节
    int perCh = kSylEdChRows;
    int chPages = (nCh + perCh - 1) / perCh;
    if (chPages < 1) chPages = 1;
    if (a.ui.scroll >= chPages) a.ui.scroll = chPages - 1;
    if (a.ui.scroll < 0) a.ui.scroll = 0;
    int chStart = a.ui.scroll * perCh;

    for (int i = 0; i < perCh; ++i) {
        int idx = chStart + i;
        if (idx >= nCh) break;
        const SyllabusChapter& c = a.sylEd.chapters[(size_t)idx];
        Gdiplus::Rect r = SylEdChRect(i);
        bool on  = (a.ui.sylEdCh == idx);
        bool hot = (a.ui.hover == idx);
        RR(g, r, 10, (on || hot) ? kCardHot : kCard,
           on ? kAccent : Color::MakeARGB(120, 90, 90, 110), on ? 2.2f : 1.2f);

        std::wstring nm = L"第" + WFromInt(idx + 1) + L"章 " + c.name;
        Gdiplus::Font fn(L"Microsoft YaHei", 15);
        Gdiplus::Rect nr(r.X + 14, r.Y + 8, 190, r.Height - 16);
        LeftIn(g, nm, fn, nr, on ? kText : kText);

        // 右上角标出这一章有没有配题——没配题的章讲完就过，不考。
        // 这个必须在界面上能看出来，否则"这章怎么不考试"只能靠猜。
        Gdiplus::Font ft(L"Microsoft YaHei", 12);
        Gdiplus::Rect tr(r.X + r.Width - 110, r.Y + 12, 96, 24);
        std::wstring tag = c.task.HasQuiz()
            ? (WFromInt((int)c.task.opts.size()) + L"选 · 答案" + WFromInt(c.task.answer))
            : L"无题";
        RightIn(g, tag, ft, tr, c.task.HasQuiz() ? kTextDim : kTextDim);
    }
    {
        Gdiplus::Font fp(L"Microsoft YaHei", 12);
        Gdiplus::Rect pr(kSylEdChX, 104, kSylEdChW, 24);
        int shownTo = (a.ui.scroll + 1) * perCh;
        if (shownTo > nCh) shownTo = nCh;
        LeftIn(g, L"章节（" + WFromInt(a.ui.scroll * perCh + 1) + L"~"
                  + WFromInt(shownTo) + L" / 共"
                  + WFromInt(nCh) + L"）", fp, pr, kTextDim);
    }

    // ---- 左栏按钮：翻页 + 增删章
    const wchar_t* const cb[4] = { L"上一页", L"下一页", L"新增章", L"删除章" };
    for (int i = 0; i < 4; ++i) {
        Gdiplus::Rect r = SylEdChBtnRect(i);
        bool grey = false;
        if (i == 0 && a.ui.scroll <= 0) grey = true;
        if (i == 1 && a.ui.scroll >= chPages - 1) grey = true;
        if (i == 3 && nCh <= 0) grey = true;
        bool hot = (a.ui.hover == SylEdChBtnHit(i)) && !grey;
        RR(g, r, 9, hot ? kCardHot : kCard,
           grey ? Color::MakeARGB(80, 90, 90, 110) : kAccent, hot ? 2.0f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 13);
        std::wstring t = cb[i];
        if (i == 3 && a.ui.sylEdDelCh) t = L"再点一次";
        Center(g, t, f, r, grey ? kTextDim : kText);
    }

    // ---- 右栏：选中那章的字段
    std::vector<SylEdField> v = SylEdFields(a);
    int perFd = kSylEdFdRows;
    int fdPages = (int)((v.size() + perFd - 1) / perFd);
    if (fdPages < 1) fdPages = 1;
    if (a.ui.sylEdFdScroll >= fdPages) a.ui.sylEdFdScroll = fdPages - 1;
    if (a.ui.sylEdFdScroll < 0) a.ui.sylEdFdScroll = 0;
    int fdStart = a.ui.sylEdFdScroll * perFd;

    if (a.ui.sylEdCh < 0) {
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Gdiplus::Rect r(kSylEdFdX, 200, kSylEdFdW, 50);
        Center(g, L"（先在左边选一章）", f, r, kTextDim);
    }
    for (int i = 0; i < perFd; ++i) {
        int idx = fdStart + i;
        if (idx >= (int)v.size()) break;
        Gdiplus::Rect r = SylEdFdRect(i);
        bool on  = (a.ui.sylEdRow == idx);
        bool hot = (a.ui.hover == 100 + idx);
        RR(g, r, 10, (on || hot) ? kCardHot : kCard,
           on ? kAccent : Color::MakeARGB(120, 90, 90, 110), on ? 2.2f : 1.2f);

        Gdiplus::Rect kr(r.X + 16, r.Y + 8, 150, r.Height - 16);
        Gdiplus::Font fk(L"Microsoft YaHei", 14);
        Center(g, v[(size_t)idx].cap, fk, kr, kTextDim);

        Gdiplus::Rect vr(r.X + 178, r.Y + 8, r.Width - 200, r.Height - 16);
        // 值里可能有换行（选项是一段代码），显示成一行，不然会溢出卡片
        std::wstring shown = v[(size_t)idx].val;
        for (size_t k = 0; k < shown.size(); ++k)
            if (shown[k] == L'\n' || shown[k] == L'\r') shown[k] = L' ';
        if (shown.size() > 42) shown = shown.substr(0, 42) + L"…";
        Gdiplus::Font fv(L"Microsoft YaHei", 14);
        Center(g, shown.empty() ? L"（空）" : shown, fv, vr,
               shown.empty() ? kTextDim : kText);
    }

    // ---- 右下按钮：加选项 / 删选项 / 保存
    const wchar_t* const bb[3] = { L"加一个选项", L"删最后一个", L"保存" };
    for (int i = 0; i < 3; ++i) {
        Gdiplus::Rect r = SylEdBtnRect(i);
        bool grey = (i != 2 && a.ui.sylEdCh < 0);
        // 【只查 >= 0 是不够的】删章后 sylEdCh 可能停在越界处，
        // 绘制时撞上同样是断言失败。取不到就当"没有选中章"处理。
        const SyllabusChapter* ec =
            (a.ui.sylEdCh >= 0 && a.ui.sylEdCh < (int)a.sylEd.chapters.size())
                ? &a.sylEd.chapters[(size_t)a.ui.sylEdCh] : nullptr;
        if (i == 0 && ec && ec->task.opts.size() >= 6) grey = true;
        if (i == 1 && ec && ec->task.opts.empty())      grey = true;
        bool hot = (a.ui.hover == SylEdBtnHit(i)) && !grey;
        RR(g, r, 10, hot ? kCardHot : kCard,
           grey ? Color::MakeARGB(80, 90, 90, 110) : kAccent, hot ? 2.0f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Center(g, bb[i], f, r, grey ? kTextDim : kText);
    }

    Gdiplus::Font fh(L"Microsoft YaHei", 13);
    Gdiplus::Rect hr(150, kScreenH - 40, 980, 24);
    Center(g, L"点一行改它，改完点「保存」写回 syllabus.ini　·　背景/开场曲留空 = 交给她自己挑",
           fh, hr, kTextDim);
}

static int SyllabusEditHitTest(const App& a, int x, int y) {
    auto inRect = [&](const Gdiplus::Rect& r) {
        return x >= r.X && x < r.X + r.Width && y >= r.Y && y < r.Y + r.Height;
    };
    if (inRect(CardBackRect())) return CardBackHit();
    for (int i = 0; i < 3; ++i)
        if (inRect(SylEdBtnRect(i))) return SylEdBtnHit(i);
    for (int i = 0; i < 4; ++i)
        if (inRect(SylEdChBtnRect(i))) return SylEdChBtnHit(i);

    std::vector<SylEdField> v = SylEdFields(a);
    int fdStart = a.ui.sylEdFdScroll * kSylEdFdRows;
    for (int i = 0; i < kSylEdFdRows; ++i) {
        int idx = fdStart + i;
        if (idx >= (int)v.size()) break;
        if (inRect(SylEdFdRect(i))) return 100 + idx;
    }
    int chStart = a.ui.scroll * kSylEdChRows;
    for (int i = 0; i < kSylEdChRows; ++i) {
        int idx = chStart + i;
        if (idx >= (int)a.sylEd.chapters.size()) break;
        if (inRect(SylEdChRect(i))) return idx;
    }
    return -1;
}

void UiWheel(App& a, int delta) {
    //
    // ---- 流程图：章节多于一屏时翻页
    //
    // 必须抢在存档页自己的滚动之前——两者共用 ui 的滚轮入口，
    // 不先拦下来就变成"想翻流程图、翻的却是槽列表"。
    if (a.ui.flowOpen) {
        int count = 0;
        if (a.ui.flowSlot >= 0 && a.ui.flowSlot < (int)a.slots.size())
            FlowChapterNames(a.slots[(size_t)a.ui.flowSlot], count);
        int maxScroll = count - FlowVisRows();
        if (maxScroll < 0) maxScroll = 0;
        a.ui.flowScroll += (delta > 0) ? -1 : 1;
        if (a.ui.flowScroll < 0) a.ui.flowScroll = 0;
        if (a.ui.flowScroll > maxScroll) a.ui.flowScroll = maxScroll;
        return;
    }
    int pages = 1;
    if (a.ui.screen == Screen::CharCard) {
        // 两栏（已绑定 / 已解绑）各算各的页数：共用 a.ui.scroll，
        // 若按其中一栏算，在另一栏就会翻出越界的页。
        size_t n = a.ui.cardShowUnbound ? a.chars.Unbound().size()
                                        : a.chars.Selectable().size();
        pages = (int)((n + (kCdCols * kCdRowsVis) - 1) / (kCdCols * kCdRowsVis));
    } else if (a.ui.screen == Screen::AssetLib) {
        // 注释编辑态不翻页：这时候网格根本没画出来
        if (a.ui.noteEdit) return;
        pages = (int)(a.ui.assetNames.size() + (kAsCols * kAsRows) - 1) / (kAsCols * kAsRows);
    } else if (a.ui.screen == Screen::Avatar) {
        pages = (int)(a.ui.avatarPaths.size() + (kAvCols * kAvRows) - 1) / (kAvCols * kAvRows);
    } else if (a.ui.screen == Screen::Syllabus) {
        pages = (int)(a.syllabusPacks.size() + kSyRows - 1) / kSyRows;
    } else if (a.ui.screen == Screen::SyllabusEdit) {
        // 滚轮滚【右栏字段列表】：左栏的章节有翻页按钮，
        // 而字段列表没有（14 项一屏装不下，100 章的剧本尤其容易超）。
        // 这里直接改 sylEdFdScroll 后返回——共用下面那段会去滚 a.ui.scroll，
        // 也就是把左栏滚走了，跟"滚的是右边"对不上。
        int fp = (int)((SylEdFields(a).size() + kSylEdFdRows - 1) / kSylEdFdRows);
        if (fp <= 1) { a.ui.sylEdFdScroll = 0; return; }
        int d = (delta > 0) ? -1 : 1;
        a.ui.sylEdFdScroll += d;
        if (a.ui.sylEdFdScroll < 0) a.ui.sylEdFdScroll = 0;
        if (a.ui.sylEdFdScroll > fp - 1) a.ui.sylEdFdScroll = fp - 1;
        // 翻页后编辑框要收起来：它还停在旧行号对应的坐标上，
        // 而那个位置现在显示的是另一项——看着像"打字打到了别的字段里"。
        if (a.hEdit) ShowWindow(a.hEdit, SW_HIDE);
        a.ui.sylEdRow = -1;
        return;
    }
    if (pages <= 1) return;
    int d = (delta > 0) ? -1 : 1;
    int old = a.ui.scroll;
    a.ui.scroll += d;
    if (a.ui.scroll < 0) a.ui.scroll = 0;
    if (a.ui.scroll > pages - 1) a.ui.scroll = pages - 1;
    // 翻页后旧的高亮就作废了：hover 存的是【全局下标】，
    // 同一个下标在上一页和这一页指的是两个不同的素材。
    // 不清掉的话鼠标不动时高亮会停在上一页那个位置，看着像"选错了"。
    if (a.ui.scroll != old) a.ui.hover = -1;
}
// 左上角「← 返回」—— 去哪儿，只在这一处定义
//
// 为什么必须集中
// 原来每个子界面在自己的 `hit == -2` 分支里写返回目标（素材页回角色卡、
// 人设页回素材页……），而点击处理最前面有个通用拦截：
// if (hit == -2) { ...GoScreen(Screen::Title); return 0; }
// 它先命中并 return，于是那些分支一行都执行不到
// 玩家从素材页点返回，直接回到主页，而不是回到上一层的角色卡。
// 分散写 + 前面有拦截 = 写了等于没写，而且看代码看不出来。
//
// 现在目标只在这张表里写一遍，离开时的清场也只做一次。
// 加新界面时改这里就行，不用再复制一段 -2 分支。
static Screen BackTargetFor(const App& a) {
    switch (a.ui.screen) {
    // 角色卡这条链：标题 -> 角色卡 -> 素材页 -> {人设页 -> 人设全文/前世记忆, 头像页}
    case Screen::CharCard:     return Screen::Title;
    case Screen::AssetLib:     return Screen::CharCard;
    case Screen::Persona:      return Screen::AssetLib;
    case Screen::PersonaText:  return Screen::Persona;
    case Screen::Memory:       return Screen::Persona;
    case Screen::Avatar:       return Screen::AssetLib;
    // 剧本这条链：标题 -> 剧本列表 -> 剧本编辑
    case Screen::SyllabusEdit: return Screen::Syllabus;
    // 局内点开的存档界面，返回要回游戏而不是标题
    case Screen::SaveLoad:     return (a.ui.saveMode == 1) ? Screen::Play : Screen::Title;
    // 设置 / 剧本列表等顶层界面
    default:                   return Screen::Title;
    }
}

// 离开任何子界面都要做的清场。
// 原来散在各界面的 -2 分支里，抄漏一处就是"编辑框还停在屏幕上"——
// 而那个位置现在画的是别的界面，看着像是打字打进了上一页。
static void LeaveScreenCleanup(App& a) {
    // 剧本编辑要把编辑框里没提交的字收进内存副本，
    // 否则"点返回"会丢掉刚打完的那一格（但确实不该写盘：没点保存就是丢弃）。
    if (a.ui.screen == Screen::SyllabusEdit) SylEdCommitField(a);
    if (a.hEdit) ShowWindow(a.hEdit, SW_HIDE);
    a.ui.personaRow      = -1;
    a.ui.personaTextEdit = false;
    a.ui.memRow          = -1;
    a.ui.sylEdRow        = -1;
}
// 角色卡 —— 素材增删 + 注释编辑 + 人设编辑
// 为什么要有这套界面，而不是留着
// 核心玩法是"角色包可更换、素材随意增删"。而旧的背景库只管 bg 一类，
// pose / bgm 想加想删只能去资源管理器手工丢文件——换包这件事缺了一大半。
// 另外它有个"通用"系列（素材不属于任何角色），跟角色包可更换直接冲突：
// 换包时那些通用素材就成了孤儿。
//
// 导入和注释必须是同一步
// 分开做会留下一个窗口期：素材进了目录、白名单已经扫到它、模型每轮都能选它，
// 而它没有注解。模型看到一堆没说明的选项只能瞎猜
// "神社夜晚被当成适合正式对话"就是这么来的。
// 所以导入完直接进注释编辑，中间态不存在。
// 批量导入时逐个弹，能跳、能中途退出；退出后剩下的仍在"缺注解"列表里，
// 不会无声无息地漏掉。
//
// 注释为什么三类共用一套代码
// char.ini 的 [AssetMood] 是"素材名 -> 一句话说明"，三类素材混在同一张表里，
// 靠名字区分。所以编辑逻辑只有一份，不必按类别各写一遍。
//
// 只能在标题页未开局时编辑
// 局内 chapterBg_ 可能正指向
// 会突然换素材。局内编辑要做全套失效处理，风险高收益低，索性不给入口。
// 编辑框字号重算，定义在文件后部（跟布局/字体那块在一起），这里先声明。
static void UpdateEditFont(bool code);

static const CharDef* CardChar(const App& a) {
    if (a.ui.cardId.empty()) return nullptr;
    return a.chars.Find(a.ui.cardId);
}

static std::wstring CardIni(const App& a) {
    const CharDef* d = CardChar(a);
    if (!d || d->packDir.empty()) return L"";
    return PathJoin(d->packDir, L"char.ini");
}

// 内置兜底角色没有 char.ini，编辑不了。这种情况要当场说清楚，
// 而不是让玩家写半天发现没保存。
static bool CardWritable(const App& a) {
    std::wstring ini = CardIni(a);
    return !ini.empty() && FileExists(ini);
}

static const wchar_t* CardKindLabel(int k) {
    if (k == 0) return L"立绘";
    if (k == 1) return L"背景";
    return L"音乐";
}

// 素材目录。口径必须跟 ScanVisibleAssets 一致：
// 角色包里已经是绝对路径，散装的才拼 assetDir。
// 两边不一致会出现"界面里看得到、模型却选不到"这种最难查的错位。
static std::wstring CardDir(const App& a) {
    const CharDef* d = CardChar(a);
    if (!d) return L"";
    const bool isPack = !d->packDir.empty();
    if (a.ui.assetKind == 0) return d->spriteDir;
    if (a.ui.assetKind == 1) {
        std::wstring dir = d->bgDir.empty() ? L"bg" : d->bgDir;
        return isPack ? dir : PathJoin(a.assetDir, dir);
    }
    std::wstring dir = d->bgmDir.empty() ? L"bgm" : d->bgmDir;
    return isPack ? dir : PathJoin(a.assetDir, dir);
}

static const wchar_t* const* CardExts(int kind) {
    static const wchar_t* const kImg[] = {
        L".png", L".jpg", L".jpeg", L".bmp", L".PNG", L".JPG", L".JPEG", L".BMP", nullptr };
    static const wchar_t* const kWav[] = { L".wav", L".WAV", nullptr };
    return (kind == 2) ? kWav : kImg;
}

// 立绘：模型看到的名字是【造型名】（去掉了 key 前缀），
// 磁盘上的文件却是 "key_造型名.png"。两边名字不一致，
// 所以列表用【模型看到的名字】（注释键也是这个），删文件时再反查回去。
static std::wstring CardPoseFile(const App& a, const std::wstring& poseName) {
    const CharDef* d = CardChar(a);
    if (!d || d->spriteDir.empty()) return L"";
    std::vector<std::wstring> cands;
    if (!d->chKey.empty()) cands.push_back(PathJoin(d->spriteDir, d->chKey + L"_" + poseName));
    cands.push_back(PathJoin(d->spriteDir, poseName));
    // 服装子目录写法：sprite\校服\害羞.png
    std::vector<std::wstring> subs = ListDirs(d->spriteDir);
    for (size_t i = 0; i < subs.size(); ++i) {
        std::wstring leaf = subs[i];
        size_t sl = leaf.find_last_of(L"\\/");
        if (sl != std::wstring::npos) leaf = leaf.substr(sl + 1);
        if (leaf.empty() || leaf[0] == L'_') continue;
        cands.push_back(PathJoin(subs[i], poseName));
        if (!d->chKey.empty()) cands.push_back(PathJoin(subs[i], d->chKey + L"_" + poseName));
    }
    const wchar_t* const* ex = CardExts(0);
    for (size_t i = 0; i < cands.size(); ++i)
        for (int e = 0; ex[e]; ++e)
            if (FileExists(cands[i] + ex[e])) return cands[i];
    return L"";
}

// 清掉没有对应素材的注解（定义在后，这里先声明）。
// commit=false 只点名不动手（供素材页提示），commit=true 才真删。
static int CardPruneOrphanNotes(App& a, bool commit);

static void CardRefresh(App& a) {
    a.ui.assetNames.clear();
    const CharDef* d = CardChar(a);
    if (!d) return;

    if (a.ui.assetKind == 0) {
        // 用模型看到的那份名单，注释键也是它
        VisibleAssets v = ScanVisibleAssets(d, a.assetDir);
        a.ui.assetNames = v.pose;
    } else {
        std::wstring dir = CardDir(a);
        if (dir.empty()) return;
        const wchar_t* const* ex = CardExts(a.ui.assetKind);
        std::vector<std::wstring> files;
        for (int i = 0; ex[i]; ++i) {
            std::vector<std::wstring> one = ListFiles(dir, ex[i]);
            files.insert(files.end(), one.begin(), one.end());
        }
        for (size_t i = 0; i < files.size(); ++i) {
            std::wstring n = PathStem(files[i]);
            if (n.empty()) continue;
            if (std::find(a.ui.assetNames.begin(), a.ui.assetNames.end(), n) == a.ui.assetNames.end())
                a.ui.assetNames.push_back(n);
        }
        std::sort(a.ui.assetNames.begin(), a.ui.assetNames.end());
    }

    if (a.ui.assetPick >= (int)a.ui.assetNames.size()) a.ui.assetPick = (int)a.ui.assetNames.size() - 1;
    a.ui.assetConfirmDel = false;
    a.ui.lastDelErr = 0;                 // 换角色/换类别后旧错误码不该再弹
    a.rend.ClearCache();
    // 只点名，不动手：真删发生在"进素材页且已经提醒过一次"的时候（GoScreen）。
    // 切类别/导入/删除都会走这里，若在这里就删，玩家还没看见提示就没了。
    CardPruneOrphanNotes(a, false);
}

// 缩略图路径（不含扩展名）。立绘要反查文件，背景/音乐直接拼目录。
static std::wstring CardThumbPath(const App& a, const std::wstring& name) {
    if (a.ui.assetKind == 0) return CardPoseFile(a, name);
    return PathJoin(CardDir(a), name);
}
// 这个素材的注解可能写在哪些键名下。
//
// 为什么要多个候选
// 立绘那一路，界面/模型用的是"服装_表情"（校服_平静），
// 而作者手写的注解很可能只写了表情名（平静）—— 两边都是合理的写法。
// 删除素材时只拿其中一个名字去删，找不到就静默失败：
// 图删了、char.ini 里那一行还在，作者看到的就是"删了素材注解不同步"。
// 所以两个名字都试一遍，试到哪个删哪个。
//
// 两个方向都要试，只试一个方向会漏
//
// · 正向 列表名"校服_平静" -> 也找"平静"（复合名 -> 表情名）
// · 反向 列表名"平静" -> 也找"校服_平静"（表情名 -> 复合名）
//
// 反向这条原来没有，而它恰恰是更常见的那一侧：
// 多套服装时 ScanVisibleAssets 交给模型的是表情（pose = faceOrder，
// 服装归 outfit 单独走），于是界面列表里显示的是"平静"；
// 而作者按文件全名写的注解是"校服_平静"。
// 只试正向的话，读到空、删不掉、写一条又变成两条并存。
//
// 反向靠扫 ini 实现，不靠拼名字
// 服装名叫什么只有文件知道（校服/忍者服/私服……），拼不出来。
// 所以直接枚举 [AssetMood] 已有的键，凡是"以 _<name> 结尾"、
// 或"下划线后面那截正好等于 name"的，都算同一张脸。
static std::vector<std::wstring> CardNoteKeysFor(const App& a, const std::wstring& name) {
    std::vector<std::wstring> out;
    if (name.empty()) return out;
    out.push_back(name);

    std::wstring ini = CardIni(a);
    if (!ini.empty()) {
        std::wstring suf = L"_" + name;
        std::vector<std::wstring> keys = IniEnumKeys(ini, L"AssetMood");
        for (size_t i = 0; i < keys.size(); ++i) {
            const std::wstring& k = keys[i];
            if (k == name) continue;
            bool hit = false;
            // 反向 A：校服_平静（以 _平静 结尾）
            if (k.size() > suf.size() &&
                k.compare(k.size() - suf.size(), suf.size(), suf) == 0) hit = true;
            // 反向 B：服装名里自己带下划线时（角色A_校服_平静），取末段比对
            if (!hit && a.ui.assetKind == 0) {
                size_t us = k.rfind(L'_');
                if (us != std::wstring::npos && k.substr(us + 1) == name) hit = true;
            }
            if (hit && std::find(out.begin(), out.end(), k) == out.end()) out.push_back(k);
        }
    }

    // 正向：列表名带下划线时，后半段也算（校服_平静 -> 平静）
    if (a.ui.assetKind == 0) {
        size_t us = name.find(L'_');
        if (us != std::wstring::npos && us + 1 < name.size()) {
            std::wstring tail = name.substr(us + 1);
            if (std::find(out.begin(), out.end(), tail) == out.end()) out.push_back(tail);
        }
    }
    return out;
}
// 读注解也要走候选，不能只按列表名精确查。
//
// 只按 name 查的后果
// 列表显示"平静"、注解写在"校服_平静"下 —— 精确查返回空，
// 界面显示"这个素材还没写注解"。作者于是写一条，写到"平静"下，
// 于是同一张脸出现两条注解：一条模型读得到（在清单名下的那条未必），
// 一条读不到。删素材时又只删得掉其中一条。
static std::wstring CardNoteGet(const App& a, const std::wstring& name) {
    std::wstring ini = CardIni(a);
    if (ini.empty()) return L"";
    std::vector<std::wstring> keys = CardNoteKeysFor(a, name);
    for (size_t i = 0; i < keys.size(); ++i) {
        std::wstring v = IniGetStr(ini, L"AssetMood", keys[i].c_str(), L"");
        if (!v.empty()) return v;
    }
    return L"";
}

static bool CardNoteSet(const App& a, const std::wstring& name, const std::wstring& text) {
    if (!CardWritable(a)) return false;
    std::wstring ini = CardIni(a);
    //
    // ---- 清空注解必须真的删掉这一行，不能只把值写空
    //
    // IniSetStr(..., L"") 留下的是 `名字 = ` —— 一个值为空的键。
    // 它仍会出现在 [AssetMood] 的枚举结果里，于是：
    // · 删了素材之后，char.ini 里永久留着一行指向不存在素材的空注解
    // （截图文件名里带时间，便于按轮次对照）；
    // · 作者改素材时看到一堆"明明删了怎么还在"的键，以为同步坏了。
    // 值空 == 没注解，所以直接删键，效果一样、文件更干净。
    //
    // 返回值 = 写盘成功删/写失败必须传出去，让界面能说出"没保存成"，
    // 而不是一律提示"已保存"——那种提示比不提示更糟，它会让人以为文件是对的。
    bool ok = true;
    std::vector<std::wstring> keys = CardNoteKeysFor(a, name);
    if (text.empty()) {
        for (size_t i = 0; i < keys.size(); ++i)
            if (IniHasKey(ini, L"AssetMood", keys[i].c_str()))
                if (!IniDelKey(ini, L"AssetMood", keys[i].c_str())) ok = false;
    } else {
        //
        // ---- 写之前先把同一张脸的其他键名删掉
        // 注解写在"校服_平静"下、作者改的是列表里的"平静"
        // 直接写会变成两条并存：一条模型读得到、一条读不到，
        // 改哪条要看运气，删素材时又只删得掉一条。
        // 所以写新值前把候选里除 name 以外的都清掉，保证一个素材只有一条。
        for (size_t i = 0; i < keys.size(); ++i) {
            if (keys[i] == name) continue;
            if (IniHasKey(ini, L"AssetMood", keys[i].c_str()))
                if (!IniDelKey(ini, L"AssetMood", keys[i].c_str())) ok = false;
        }
        if (!IniSetStr(ini, L"AssetMood", name.c_str(), text)) ok = false;
    }
    //
    // ---- 内存里那份也要跟着改
    // ScanVisibleAssets 是拿 def->assetMood 去填 v.mood 的。只写 ini 不动内存，
    // 重扫之后白名单里的说明还是旧的那句——界面显示"已保存"，
    // 模型看到的却是改之前的内容。
    CharDef* d = const_cast<CharDef*>(CardChar(a));
    if (d) {
        if (text.empty()) {
            for (size_t i = 0; i < keys.size(); ++i) d->assetMood.erase(keys[i]);
        } else d->assetMood[name] = text;
    }
    return ok;
}
// 改完素材或注释必须让白名单失效，否则界面改了、游戏里还是旧的。
//
// 光设 whitelistReady=false 还不够
// EnsureWhitelist 比对的是文件名指纹，只改注释的话指纹不变，
// 会判定"没动过"直接返回——白名单里的说明还是旧的。
// 连 stamp 一起清才能真正重建。
static void CardInvalidateAssets() {
    g_app.whitelistReady = false;
    g_app.whitelistStamp.clear();
}
// 孤儿素材注解清理
//
// 判定只看"素材在不在"，不看注解写没写：
// ① 有素材、没注解 -> 保留。空注解 = 还没写说明，作者随时会补
// ② 没素材、有注解 -> 清。素材不在，这段说明没有任何读者
// ③ 没素材、没注解 -> 清
//
// ★ 按"值空"去清会把刚导入的一批图连同位置一起清掉，而且不报错
// 作者只会发现"注解怎么都写不住"。
// ★ 删掉的是作者亲手写过的字，所以分两步：打开素材页只列出待清的名字，
// 再进一次才真的删。中间这一次机会也是改名错误唯一的暴露点
// 素材名打错一个字，注解立刻变孤儿，而且完全不报错：她只是再也不去那个地方。
// ★ 三类清单全空 = 目录没扫到（包没装好、路径配错）。这时"所有名字都不在清单里"
// 会把整段注解清空，那是灾难。扫不到就当没看见，宁可留着。
//
// 名字会打进日志：char.ini 是纯文本，真清掉了还能照着日志把名字补回来。
//
// commit=false：每次刷新都走一遍，只点名、不动手（供提示显示）。
// commit=true ：进素材页时、且已经提醒过一次，才真的删。
// 一条注解的键名，到底指不指向一个真实存在的素材。
//
// 只按精确名字比的后果：注解写在"校服_平静"下会被当成孤儿清掉
// 多套服装时 ScanVisibleAssets 交给模型/界面的是表情（pose = faceOrder，
// 服装归 outfit 单独走），所以清单里只有"平静"；而作者按文件全名写的注解
// 是"校服_平静"。精确比对两边都不相等 —— 于是这条注解被判成孤儿删掉。
// 图明明在、说明也明明是作者刚写的，却被清得悄无声息。
// 所以比对要顺着"服装 × 表情 = 真实文件"这张真值表走一遍。
//
// 只对立绘做下划线拆分
// 背景名里的下划线是时段的正当用法（镇上的街道_白天），拆开就全乱了。
static bool AssetNoteKeyIsLive(const std::wstring& key, const VisibleAssets& v) {
    if (key.empty()) return false;
    for (size_t i = 0; i < v.pose.size(); ++i) if (v.pose[i] == key) return true;
    for (size_t i = 0; i < v.bg.size(); ++i)   if (v.bg[i] == key) return true;
    for (size_t i = 0; i < v.bgm.size(); ++i)  if (v.bgm[i] == key) return true;

    size_t us = key.rfind(L'_');
    if (us == std::wstring::npos || us == 0 || us + 1 >= key.size()) return false;
    std::wstring tail = key.substr(us + 1);     // 校服_平静 -> 平静
    std::wstring head = key.substr(0, us);      // 校服_平静 -> 校服

    // 末段是真实表情 -> 同一张脸（"角色A_校服_平静"这种三段名也有救）
    for (size_t i = 0; i < v.pose.size(); ++i)  if (v.pose[i] == tail) return true;
    for (size_t i = 0; i < v.emote.size(); ++i) if (v.emote[i] == tail) return true;

    // 首段是真实服装 + 末段是真实表情 -> 合成出来就是一张真实存在的图
    bool headIsOutfit = false;
    for (size_t i = 0; i < v.outfit.size(); ++i) if (v.outfit[i] == head) headIsOutfit = true;
    if (!headIsOutfit) return false;
    for (size_t i = 0; i < v.pose.size(); ++i)  if (v.pose[i] == tail) return true;
    for (size_t i = 0; i < v.emote.size(); ++i) if (v.emote[i] == tail) return true;
    return false;
}

//
// commit=false：只点名，一条都不动 —— 名单留在 a.ui.orphanNames 供提示显示。
// commit=true ：真删。不写回收文件（见上面"不存回收文件"）。
static int CardPruneOrphanNotes(App& a, bool commit) {
    std::wstring ini = CardIni(a);
    if (ini.empty()) { a.ui.orphanNames.clear(); return 0; }
    const CharDef* d = CardChar(a);
    if (!d) { a.ui.orphanNames.clear(); return 0; }

    // 真实存在的素材（扫目录得出，跟模型看到的是同一份）
    VisibleAssets v = ScanVisibleAssets(d, a.assetDir);
    if (v.pose.empty() && v.bg.empty() && v.bgm.empty()) {
        a.ui.orphanNames.clear();            // 扫不到就当没看见，宁可留着
        return 0;
    }

    std::vector<std::wstring> keys = IniEnumKeys(ini, L"AssetMood");
    std::vector<std::wstring> dead;          // 没有对应素材的注解键名
    int nWithNote = 0;
    std::wstring names;                      // 被删掉的键名，打进日志便于找回
    for (size_t i = 0; i < keys.size(); ++i) {
        const std::wstring& k = keys[i];
        std::wstring val = IniGetStr(ini, L"AssetMood", k.c_str(), L"");
        // 指着一个真实存在的素材 -> 保留，【不管注解写没写】（规则①）
        if (AssetNoteKeyIsLive(k, v)) continue;
        dead.push_back(k);
        if (!names.empty()) names += L"、";
        names += k;
        if (!val.empty()) { names += L"(有注解)"; ++nWithNote; }
    }

    // ---- 只扫描：把名单交给素材页显示"再进来就清了"，这一轮一条都不动。
    if (!commit) {
        a.ui.orphanNames = dead;
        return (int)dead.size();
    }

    if (dead.empty()) { a.ui.orphanNames.clear(); return 0; }

    for (size_t i = 0; i < dead.size(); ++i) {
        IniDelKey(ini, L"AssetMood", dead[i].c_str());
        // 内存里那份也跟着删：ScanVisibleAssets 是拿它填 v.mood 的，
        // 只删文件不删内存，重扫之后模型看到的还是旧注解。
        CharDef* m = const_cast<CharDef*>(d);
        if (m) m->assetMood.erase(dead[i]);
    }
    a.ui.orphanNames.clear();
    CardInvalidateAssets();
    AppLog(L"清掉了 %d 条没有对应素材的注解（其中 %d 条写有内容）：%s",
           (int)dead.size(), nWithNote, names.c_str());
    return (int)dead.size();
}

// 导入单个素材文件。对话框导入和拖放导入共用这一份，
// 免得两处各写一遍、改了这边漏那边（"导入成功却选不到"就是这么来的）。
static bool CardImportOne(App& a, const std::wstring& src) {
    if (src.empty()) return false;
    std::wstring dir = CardDir(a);
    if (dir.empty()) return false;
    EnsureDir(dir);
    // 名字清理：文件名首尾的空格在资源管理器里根本看不出来，
    // 却会让精确匹配永远失败（"思考 " 匹配不上 "思考"）。
    std::wstring stem = Trim(PathStem(src));
    if (stem.empty()) return false;
    std::wstring ext;
    size_t dot = src.rfind(L'.');
    if (dot != std::wstring::npos) ext = ToLower(src.substr(dot));
    if (a.ui.assetKind == 2) ext = L".wav";
    else if (ext != L".png" && ext != L".jpg" && ext != L".jpeg" && ext != L".bmp") ext = L".png";
    std::wstring dst = PathJoin(dir, stem + ext);
    if (!CopyFileW(src.c_str(), dst.c_str(), FALSE)) return false;
    a.ui.noteQueue.push_back(stem);
    return true;
}

static int CardImport(App& a) {
    static wchar_t buf[32768] = { 0 };
    buf[0] = L'\0'; buf[1] = L'\0';

    OPENFILENAMEW ofn{};
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = a.hwnd;
    ofn.lpstrFilter = (a.ui.assetKind == 2)
        ? L"音频文件\0*.wav\0所有文件\0*.*\0"
        : L"图片文件\0*.png;*.jpg;*.jpeg;*.bmp\0所有文件\0*.*\0";
    ofn.lpstrFile = buf;
    ofn.nMaxFile = 32768;
    ofn.Flags = OFN_EXPLORER | OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST |
                OFN_ALLOWMULTISELECT | OFN_HIDEREADONLY;
    ofn.lpstrTitle = (a.ui.assetKind == 2)
        ? L"选择要导入的音乐（可多选）"
        : L"选择要导入的图片（可多选）";

    if (!GetOpenFileNameW(&ofn)) return 0;

    std::wstring dir = CardDir(a);
    if (dir.empty()) return 0;
    EnsureDir(dir);

    std::vector<std::wstring> parts;
    {
        const wchar_t* p = buf;
        while (*p) { parts.push_back(std::wstring(p)); p += parts.back().size() + 1; }
    }
    if (parts.empty()) return 0;

    std::vector<std::wstring> srcs;
    if (parts.size() == 1) srcs.push_back(parts[0]);
    else for (size_t i = 1; i < parts.size(); ++i) srcs.push_back(PathJoin(parts[0], parts[i]));

    int ok = 0;
    for (size_t i = 0; i < srcs.size(); ++i) {
        if (srcs[i].empty()) continue;
        if (CardImportOne(a, srcs[i])) ++ok;
        else Dbg(L"素材导入失败: %s", srcs[i].c_str());
    }
    if (ok > 0) { CardRefresh(a); CardInvalidateAssets(); }
    return ok;
}

static bool CardDelete(App& a) {
    if (a.ui.assetPick < 0 || a.ui.assetPick >= (int)a.ui.assetNames.size()) return false;
    if (!a.ui.assetConfirmDel) { a.ui.assetConfirmDel = true; return false; }

    std::wstring name = a.ui.assetNames[a.ui.assetPick];
    std::wstring path = CardThumbPath(a, name);

    // 先丢图像缓存再删文件：缓存里活着的 Image 会持有文件句柄，
    // 句柄在 → DeleteFileW 直接失败且没有提示，玩家只会以为按钮坏了。
    a.rend.ClearCache();

    bool done = false;
    DWORD lastErr = 0;
    if (!path.empty()) {
        const wchar_t* const* ex = CardExts(a.ui.assetKind);
        for (int i = 0; ex[i] && !done; ++i) {
            std::wstring p = path + ex[i];
            if (!FileExists(p)) continue;
            if (DeleteFileW(p.c_str())) { done = true; break; }
            lastErr = GetLastError();
        }
    }
    // ---- 注解要在重扫之前就知道"有没有这条"
    // CardRefresh 会重扫目录，扫完这一条就成了孤儿。
    // 先问一次"ini 里到底有没有它的注解"，才能区分两种情况：
    // 有 -> 删掉了（成功）
    // 没有 -> 注解键名跟素材名对不上，下面那条孤儿清理也救不了它
    // （它写着内容，被当成"作者先写好、图还没导入"保护起来了）
    // 这两种结果给作者的提示完全不同，混成一句"已删除"就永远查不出键名写错了。
    std::wstring ini = CardIni(a);
    bool hadNote = false;
    if (!ini.empty()) {
        std::vector<std::wstring> keys = CardNoteKeysFor(a, name);
        for (size_t i = 0; i < keys.size() && !hadNote; ++i)
            hadNote = IniHasKey(ini, L"AssetMood", keys[i].c_str());
    }

    a.ui.assetConfirmDel = false;
    CardRefresh(a);

    if (done) {
        // 注释一起清掉：留着一条指向不存在素材的说明，白名单不会显示它，
        // 但作者改素材时会困惑——"明明删了怎么还在"。
        //
        // 保存失败要说出来CardNoteSet 现在返回写盘结果。
        // 文件只读/被编辑器独占时写不进去，一律提示"已删除"会让人以为同步好了。
        bool noteOk = true;
        if (CardWritable(a)) noteOk = CardNoteSet(a, name, L"");
        CardInvalidateAssets();
        a.ui.lastDelErr = 0;
        a.ui.delNoteWarn = noteOk ? (hadNote ? 0 : 2) : 1;   // 0=都好 1=写盘失败 2=键名对不上
        a.ui.delNoteWarnName = (a.ui.delNoteWarn != 0) ? name : std::wstring();
        if (!noteOk)          AppLog(L"素材已删，但 char.ini 写不进去（只读或被占用？），注解没同步");
        else if (!hadNote)    AppLog(L"素材已删，但 char.ini 里没有名为「%ls」的注解——键名对不上时删不掉", name.c_str());
    } else {
        // lastErr 可能是 0：路径为空、或所有候选扩展名的文件都不存在。
        // 那就置一个非 0 的兜底值，否则界面判断"!=0"时不成立，玩家点了没反应。
        a.ui.lastDelErr = (lastErr != 0) ? lastErr : 1;
    }
    return done;
}
// ---------------------------------------------------------------- 绘制
// 返回按钮不再各页自己画——DrawBackdropBack 已经画了全局那一个，
// 再画一个就是左上角两个「← 返回」重叠（见 CardBackRect 的注释）。
// 角色卡列表
//
// 没有"装角色包"这一步了：加角色只有「＋ 新建角色」和「打开包目录手动放」两条路，
// 都直接作用在 assets\char 下——见上面「角色包」那一段的说明。
// 新建角色卡 —— 在 assets\char\<名字> 下建一个跟角色B / 角色A同结构的空包
//
// 为什么要有这个入口，而不是只留"装 .ckchar"
// 原来作者想加一个角色只有两条路：
// 1. 手动复制 _模板 目录 → 改名 → 改 char.ini → 手动打成 zip 改成 .ckchar
// 2. 把 .ckchar 拖进窗口
// 第 1 条没人会做：_模板 躺在 assets\char 里，作者根本不知道有这个东西，
// 而且它要求先知道"一个角色包该长什么样"——正是要教的那件事。
// 第 2 条要先有 .ckchar，而做出 .ckchar 的唯一办法就是第 1 条。
// 两条路互为前提，于是装包这个功能从头到尾没有任何人能用上。
//
// 这个入口把死锁打开：点一下，目录和 char.ini 照着现成包的样子建好，
// 作者只需要往 sprite / bg / bgm 里丢素材、在游戏里写注解。
// 分享 / 备份也一样：整个目录拷给别人，对方放进 assets\char 再点重新扫描，
// 不需要打包成任何格式。
struct NewPackResult {
    bool ok = false;
    std::wstring id;        // 建出来的角色 id（= 目录名）
    std::wstring err;       // 失败原因（人话）
};
// 名字里不能出现的字符。
// 前 9 个是 Windows 文件名非法字符；控制字符一并挡掉。
// '=' 也挡：名字会写进 [Char] Name = <名字>，值里的等号会让 ini 解析
// 把后半截当成别的东西；'[', ']' 同理（会被认成段名）。
static bool NewPackBadChar(wchar_t c) {
    return c == L'\\' || c == L'/' || c == L':' || c == L'*' || c == L'?'
        || c == L'"'  || c == L'<' || c == L'>' || c == L'|' || c == L'='
        || c == L'['  || c == L']' || c < 0x20;
}

// 生成新包的 char.ini。名字以外全是空壳，但每一段都写了"这段该填什么"——
// 空壳最怕的不是空，是作者打开以后不知道往哪写。
static std::wstring NewPackIniText(const std::wstring& name) {
    const std::wstring t = LR"LIT(; ============================================================================
;  @N@ —— 角色卡
;
;  这个文件和三个目录是「＋ 新建角色」自动生成的，
;  结构跟角色B / 角色A一模一样：
;
;    char.ini    本文件：元信息 + 人设 + 素材注解
;    sprite\     立绘（png）。文件名就是表情名，例：平静.png
;    bg\         背景（png / jpg）。文件名就是场景名，例：课室.png
;    bgm\        音乐（wav）。例：主题.wav
;    story.ini   剧情大纲。只有做剧情模式才需要，没有它照样能玩
;
;  ★素材丢进对应目录就能用，不用在这里登记★
;    往 sprite\ 放一张「得意.png」，她下一轮就能选到它。
;    但【注解】要写——注解才是她挑选的依据，不写她只知道有这么张图。
;    注解写在 [AssetMood] 段，键名要跟文件名一字不差（不含扩展名）。
;
;  ★最省事的写法：在游戏里点进这张卡 → 素材页逐个写，不用碰这个文件★
; ============================================================================

[Char]
Name = @N@
Tag = 标签
Desc = 选角界面上显示的一句话简介。
Selectable = 1
Temperature = 0.8

[Player]
; 他在这段关系里是谁。写清楚，她才知道该用什么距离和你说话
Relation = 同学
Self = 我
You = 你

[Memory]
; 我们.1 = 你们一起经历过的事（她会记得，也会主动提起）
; 习惯.1 = 她的习惯、口味、小动作
; 这是她「记得你」的全部依据，比人设更影响她怎么对你说话。
; 去掉行首的分号和空格就能生效：
; 我们.1 = 第一次见面是在……
; 习惯.1 =

[Prompt]
; 人设全文：她是谁、怎么说话、什么情况下会怎样。
; ★这是最重要的一段★ —— 写得越具体，她越像「这个人」。
; ★建议在游戏里写：点进这张卡 → 右上角「编辑人设」，写完自动存回这里★
System =
; Sample = 给她几段「我会怎么说话」的样板，比描述更管用

[Sprite]
Dir = sprite
; 立绘文件名前缀。留空则文件名直接就是表情名（平静.png）；
; 写了则认 <Key>_<表情>.png（例：角色B_平静.png）
Key =
Scale = 1.0
OffsetX = 0
OffsetY = 0

[Title]
; 主页插画（相对本包，不含扩展名）。留空就退回立绘
; Art = sprite\标题

[Theme]
; 主色，决定对话框描边 / 名字牌 / 选项高亮
Main = FFB4D2
Name = 8A2E52

[Tone]
Self = 我
You = 你

[Bg]
Dir = bg

[Emote]
[Outfit]

[Bgm]
Dir = bgm
; 主页曲（写死在这里，它会从可选清单里剔除，她既看不到也选不到）
; Title = 主题_主页

; ============================================================================
;  素材注解 —— 模型每轮看到的全部说明
;  键名必须跟 sprite\ / bg\ / bgm\ 里的【真实文件名】一致（不含扩展名）。
;  名字对不上不生效，而且【不报错】——她只是永远不去那个地方。
;  ★建议在游戏里写：点进这张卡 → 素材页 → 逐个写★
; ============================================================================
[AssetMood]
; ===== 立绘 pose =====
; 平静 = 默认状态，最稳的一张，用在没有特别情绪的时候
; 害羞 =
;
; ===== 背景 bg =====
; 课室 =
;
; ===== 音乐 bgm =====
; 主题 =
)LIT";
    // 只替换第一个占位符：名字里理论上不会再出现 @N@，但替换全部也没必要
    std::wstring out = t;
    size_t p = out.find(L"@N@");
    while (p != std::wstring::npos) { out.replace(p, 3, name); p = out.find(L"@N@", p + name.size()); }
    return out;
}

NewPackResult CreateNewCharPack(const std::wstring& rootDir, const std::wstring& rawName) {
    NewPackResult r;

    // ---- 洗名字：去掉首尾空白和不能进文件名的字符
    std::wstring name = Trim(rawName);
    std::wstring clean;
    for (size_t i = 0; i < name.size(); ++i)
        if (!NewPackBadChar(name[i])) clean.push_back(name[i]);
    clean = Trim(clean);

    if (clean.empty()) { r.err = L"名字不能为空（也不能全是符号）"; return r; }
    if (clean.size() > 40) { r.err = L"名字太长了（最多 40 个字）"; return r; }

    // ---- 重名：目录已经存在就直接挡下。
    //  不自动加后缀——"角色A" 和 "角色A2" 是两个角色，作者会以为是建失败了。
    std::wstring pack = PathJoin(rootDir, clean);
    if (FileExists(pack)) {
        r.err = L"已经有叫「" + clean + L"」的角色了（assets\\char\\ 下有同名文件夹）";
        return r;
    }

    if (!EnsureDir(pack)) { r.err = L"文件夹创建失败：" + pack; return r; }

    const wchar_t* subName[3] = { L"sprite", L"bg", L"bgm" };
    std::wstring sub[3];
    for (int i = 0; i < 3; ++i) {
        sub[i] = PathJoin(pack, subName[i]);
        if (!EnsureDir(sub[i])) { r.err = L"文件夹创建失败：" + sub[i]; return r; }
    }

    // ---- char.ini 是"这个目录算一个角色"的唯一凭据，
    //  没写出来就是不完整的包：扫得到目录、认不出角色。
    if (!WriteTextFile(PathJoin(pack, L"char.ini"), NewPackIniText(clean))) {
        r.err = L"char.ini 写入失败（目录已建好，可以手动补）";
        return r;
    }

    // ---- 三个空目录各放一句说明。
    //  空目录在资源管理器里看不出是放什么的，作者会犹豫该往哪丢；
    //  顺带说明"不用在 ini 里登记"，那是老做法留下的最大误会。
    WriteTextFile(PathJoin(sub[0], L"_放这里.txt"),
        L"立绘（png）放这里。\n"
        L"文件名就是表情名，例：平静.png、害羞.png、得意.png\n"
        L"不用在 char.ini 里登记 —— 放进来她就能选到。\n"
        L"注解在游戏里写：角色卡 → 点进这张卡 → 素材页。\n");
    WriteTextFile(PathJoin(sub[1], L"_放这里.txt"),
        L"背景（png / jpg）放这里。\n"
        L"文件名就是场景名，例：课室.png、咖啡馆_夜晚.png\n"
        L"不用在 char.ini 里登记 —— 放进来她就能选到。\n"
        L"注解在游戏里写：角色卡 → 点进这张卡 → 素材页 → 背景。\n");
    WriteTextFile(PathJoin(sub[2], L"_放这里.txt"),
        L"音乐（wav）放这里。例：主题.wav\n"
        L"除了主页曲以外的都会进她的可选清单，她按情绪挑。\n"
        L"不用在 char.ini 里登记。\n");
    //
    // ---- story.ini：跟角色B / 角色A一样，包里也有这一份
    //
    // 它是剧情模式专用的大纲，课程模式用不到，
    // 所以里面全是注释——不写 Acts（或写 0），剧本页就不会列出这本，
    // 新角色不会凭空多出一个空剧本。
    //
    // 为什么还是要建这个文件
    // 结构跟现成的包一模一样，作者照着角色B那份抄就有处可抄；
    // 而"包里没有这个文件"会被理解成"这个角色不支持剧情模式"
    // 其实只是还没写。
    WriteTextFile(PathJoin(pack, L"story.ini"),
        L"; ============================================================\n"
        L";  剧情大纲（感情曲线）—— 只有做「剧情模式」才需要\n"
        L";\n"
        L";  没写 Acts（或写 0）时，剧本页不会出现这本，课程模式照常玩。\n"
        L";  想做剧情：把下面 Acts 那行的分号去掉、填上幕数，再照 [1] 往下写。\n"
        L";\n"
        L";  ★这不是脚本，不写死任何一句台词★\n"
        L";  每一幕只规定：这一幕结束时，你们之间「该到什么位置」。\n"
        L";  她怎么走到那里、说了什么，是她当场想出来的。\n"
        L";\n"
        L";  推进：你写的 Must（那件必须发生的事）做到了，她会给信号，\n"
        L";        你点「下一幕」才走。Must 是她判断「演完没有」的依据——\n"
        L";        不写的话她只能凭感觉，那一幕就很难收。\n"
        L";        她没给，就走不了——这一幕还没完。\n"
        L"; ============================================================\n"
        L"\n"
        L"[Story]\n"
        L"; 标题：显示在剧本页上\n"
        L"; Title = 那条线的名字\n"
        L"\n"
        L"; 幕数：写了这一行（且大于 0），剧本页才会出现这本\n"
        L"; Acts = 6\n"
        L"\n"
        L"; 总纲：她会先看到这段，才知道整条线在讲什么（强烈建议写）\n"
        L"; Note = 两个人都在等对方先开口。整个故事就是那句谁也没说出口的话。\n"
        L"\n"
        L"; ---- 每一幕：照下面这个骨架复制，段名 [1] [2] [3] …… ----\n"
        L";  Name = 这一幕的名字\n"
        L";  Goal = 这一幕结束时，你们之间该到什么位置\n"
        L";  Mood = 情绪基调（惊喜、不安、想逃……）\n"
        L";  Must = 结束前必须发生的事（这也是她判断能不能进下一幕的依据）\n"
        L";  Ban  = 绝对不能发生的事（不写，她很可能第一幕就把底牌掀了）\n"
        L";  Bg   = 这一幕的场景，必须是 bg\\ 里真实存在的文件名\n"
        L";  Turns= 这一幕大概演几轮（可省，默认 4）。\n"
        L";         难的、重的幕可以写大一点，比如「代价」那幕写 8。\n"
        L";         这只是给她一个节奏感，不是上限也不是下限。\n"
        L"\n"
        L"; [1]\n"
        L"; Name =\n"
        L"; Bg   =\n"
        L"; Mood =\n"
        L"; Goal =\n"
        L"; Must =\n"
        L"; Ban  =\n"
        L"; Turns=\n");

    r.ok = true;
    r.id = clean;
    return r;
}
// 进入命名态：把共用的 EDIT 控件摆到命名框上并聚焦。
//
// 跟素材注解那套一致：编辑框由窗口过程管，这里只管定位，
// 提交放在「创建」按钮上——比靠失焦提交更不容易丢内容。
// 预填「新角色」并全选，作者直接打字就覆写，不用先删占位文字。
static void ChCardStartName(App& a) {
    a.ui.newCharName = true;
    if (!a.hEdit) return;
    int ex = 0, ey = 0, ew = 0, eh = 0;
    if (UiEditRowRect(a, ex, ey, ew, eh)) {
        a.rend.LogicToClient(ex, ey, ew, eh);
        SetWindowTextW(a.hEdit, L"新角色");
        MoveWindow(a.hEdit, ex, ey, ew, eh, TRUE);
        UpdateEditFont(false);
        ShowWindow(a.hEdit, SW_SHOW);
        SetFocus(a.hEdit);
        SendMessageW(a.hEdit, EM_SETSEL, 0, -1);
    }
}

static void ChCardEndName(App& a) {
    a.ui.newCharName = false;
    if (a.hEdit) ShowWindow(a.hEdit, SW_HIDE);
}
//
// 打开角色包目录（assets\char\）。
//
// 为什么要有这个按钮
// "把文件夹放进去"本来就是加角色的一条正规路子——尤其自己做包的时候，
// 不可能每改一次就打个 zip 再拖进来。可游戏里没有任何入口指向那个目录，
// 作者只能自己猜路径（早期版本还有个 charpacks 目录，常常猜成那个）。
// 给个按钮直接打开，比在提示里写路径可靠。
//
// 目录不存在时先建出来：空目录打开后能直接往里放包，
// 而 explorer 打开一个不存在的路径只会报错。
static void ChPackOpenDir(App& a) {
    std::wstring dir = a.charDir;
    if (dir.empty()) return;
    if (!DirExists(dir)) EnsureDir(dir);
    ShellExecuteW(a.hwnd, L"open", dir.c_str(), nullptr, nullptr, SW_SHOW);
}

static void DrawCharCard(Graphics& g, App& a) {
    DrawBackdropBack(g, a);

    const bool showUn = a.ui.cardShowUnbound;
    const std::vector<const CharDef*> unb = a.chars.Unbound();
    std::vector<const CharDef*> sel = showUn ? unb : a.chars.Selectable();

    DrawTitle(g, showUn ? (L"已解绑（" + WFromInt((long long)unb.size()) + L"）") : L"角色卡", 24);

    // ---- 按钮：0=新建 1=打开包目录 2=重新扫描 3=解绑/重新绑定 4=已解绑(N)/返回
    {
        std::wstring bl[5];
        bl[0] = L"＋ 新建角色";
        bl[1] = L"打开包目录";
        bl[2] = L"↻ 重新扫描";
        bl[3] = showUn ? L"重新绑定" : L"解绑";
        bl[4] = showUn ? L"返回列表" : (L"已解绑（" + WFromInt((long long)unb.size()) + L"）");
        for (int i = 0; i < kChCardBtnCount; ++i) {
            // 灰掉的判定：见 ChCardBtnDisabled（绘制和命中测试共用同一份）
            bool disabled = ChCardBtnDisabled(a, i);
            Gdiplus::Rect r = ChCardBtnRect(i);
            bool hot = !disabled && (a.ui.hover == ChCardBtnHit(i));
            RR(g, r, 10, disabled ? kLocked : (hot ? kCardHot : kCard),
               Color::MakeARGB(120, 90, 90, 110), hot ? 2.5f : 1.2f);
            Gdiplus::Font f(L"Microsoft YaHei", 15);
            Center(g, bl[i], f, r, disabled ? kTextDim : kText);
        }
    }

    // ---- 命名态：盖住卡片网格，只画这一个面板
    if (a.ui.newCharName) {
        Gdiplus::Font fh(L"Microsoft YaHei", 20, Gdiplus::FontStyleBold);
        Gdiplus::Rect hr(150, 168, 980, 40);
        Center(g, L"给新角色起个名字", fh, hr, kText);

        Gdiplus::Font fs(L"Microsoft YaHei", 14);
        Gdiplus::Rect s1(150, 210, 980, 26);
        Center(g, L"这个名字就是文件夹名（assets\\char\\<名字>\\），存档和「已解绑」名单也按它记",
               fs, s1, kTextDim);
        Gdiplus::Rect s2(150, 236, 980, 26);
        Center(g, L"想好再定——之后要改，得连文件夹一起手动改", fs, s2, kTextDim);

        Gdiplus::Rect box = ChCardNameBoxRect();
        RR(g, box, 10, Color::MakeARGB(60, 20, 18, 30), kAccent, 1.5f);

        const wchar_t* const nl[2] = { L"创建", L"取消" };
        for (int i = 0; i < 2; ++i) {
            Gdiplus::Rect r = ChCardNameBtnRect(i);
            bool hot = (a.ui.hover == ChCardNameBtnHit(i));
            ARGB fill = (i == 0) ? (hot ? kCardHot : kCard) : kLocked;
            RR(g, r, 10, fill, kAccent, hot ? 2.0f : 1.2f);
            Gdiplus::Font f(L"Microsoft YaHei", 16);
            Center(g, nl[i], f, r, kText);
        }
        return;
    }

    if (sel.empty()) {
        Gdiplus::Font f(L"Microsoft YaHei", 17);
        Gdiplus::Rect r(200, 300, 880, 60);
        Center(g, showUn ? L"（没有已解绑的角色包）"
                         : L"（角色库是空的——先装一个角色包）", f, r, kTextDim);
        if (!showUn && !unb.empty()) {
            Gdiplus::Font f2(L"Microsoft YaHei", 14);
            Gdiplus::Rect r2(200, 366, 880, 30);
            Center(g, L"右上角「已解绑」里还有 " + WFromInt((long long)unb.size())
                      + L" 个——它们只是没显示，文件都还在", f2, r2, kTextDim);
        }
        return;
    }

    int perPage = kCdCols * kCdRowsVis;
    int start = a.ui.scroll * perPage;
    for (int i = 0; i < perPage; ++i) {
        int idx = start + i;
        if (idx >= (int)sel.size()) break;
        const CharDef* d = sel[idx];
        Gdiplus::Rect r = CardItemRect(i);
        bool on = (a.ui.cardPick == idx) || (a.ui.hover == idx);
        RR(g, r, 14, on ? kCardHot : kCard,
           on ? kAccent : Color::MakeARGB(120, 90, 90, 110), on ? 2.5f : 1.2f);

        // 头像：优先 [Sprite] Card，没配就退回默认造型，找不到就画占位
        Gdiplus::Rect pr(r.X + (r.Width - 96) / 2, r.Y + 16, 96, 96);
        Image* img = a.rend.CharPortrait(d);
        if (img) {
            Gdiplus::RectF dst = FitRectFor(img, pr);
            g.SetClip(pr); g.DrawImage(img, dst); g.ResetClip();
        } else {
            Gdiplus::SolidBrush ph(Color::MakeARGB(80, 60, 55, 75));
            g.FillRectangle(&ph, pr);
        }

        Gdiplus::Font fn(L"Microsoft YaHei", 18, Gdiplus::FontStyleBold);
        Gdiplus::Rect nr(r.X + 10, r.Y + 120, r.Width - 20, 30);
        Center(g, d->DisplayName(), fn, nr, kText);

        Gdiplus::Font ft(L"Microsoft YaHei", 14);
        Gdiplus::Rect tr(r.X + 10, r.Y + 152, r.Width - 20, 24);
        Center(g, d->tag.empty() ? std::wstring(L"　") : d->tag, ft, tr, kTextDim);

        Gdiplus::Rect dr(r.X + 14, r.Y + 178, r.Width - 28, 30);
        Center(g, d->desc, ft, dr, kTextDim);

        // 没有 char.ini 的角色编辑不了，卡上直接标出来
        if (d->packDir.empty() || !FileExists(PathJoin(d->packDir, L"char.ini"))) {
            Gdiplus::Font fw(L"Microsoft YaHei", 12);
            Gdiplus::Rect wr(r.X + 14, r.Y + r.Height - 24, r.Width - 28, 20);
            Center(g, L"（内置角色，没有 char.ini，不可编辑）", fw, wr, kTextDim);
        }
        // 已解绑：文件都在，只是不出现在游戏里。写清楚，免得以为东西没了
        if (showUn) {
            Gdiplus::Font fu(L"Microsoft YaHei", 12);
            Gdiplus::Rect ur(r.X + 14, r.Y + r.Height - 44, r.Width - 28, 20);
            Center(g, L"已解绑 · 文件仍在，点「重新绑定」即可回来", fu, ur,
                   Color::MakeARGB(255, 210, 160, 100));
        }
    }

    Gdiplus::Font fh(L"Microsoft YaHei", 14);
    Gdiplus::Rect hr(200, kScreenH - 70, 880, 28);
    Center(g, showUn ? L"解绑只是不显示，一个文件都没删；要彻底删除请去 assets\\char\\ 下手动删"
                     : L"点一张卡进入编辑：增删素材、写注释、改人设；新角色用「＋ 新建角色」，或「打开包目录」手动放后点「重新扫描」",
           fh, hr, kTextDim);
}

// 素材页
static void DrawAssetLib(Graphics& g, App& a) {
    DrawBackdropBack(g, a);
    const CharDef* d = CardChar(a);
    DrawTitle(g, d ? (L"角色卡 · " + d->DisplayName()) : L"角色卡", 22);

    // ---- 注释编辑态：只画面板，不画网格
    if (a.ui.noteEdit) {
        Gdiplus::Font fh(L"Microsoft YaHei", 20, Gdiplus::FontStyleBold);
        Gdiplus::Rect hr(150, 170, 980, 40);
        Center(g, L"给「" + a.ui.noteName + L"」写一句说明", fh, hr, kText);

        Gdiplus::Font fs(L"Microsoft YaHei", 14);
        Gdiplus::Rect sr(150, 210, 980, 44);
        Center(g, L"这句话就是模型每轮看到的全部依据——写清它【是什么】和【什么时候用】",
               fs, sr, kTextDim);

        Gdiplus::Rect box = CardNoteBoxRect();
        RR(g, box, 10, Color::MakeARGB(60, 20, 18, 30), kAccent, 1.5f);

        if (!a.ui.noteQueue.empty()) {
            Gdiplus::Font fq(L"Microsoft YaHei", 13);
            Gdiplus::Rect qr(150, 448, 980, 26);
            Center(g, L"还有 " + WFromInt((long long)a.ui.noteQueue.size()) + L" 个没写（可以跳过）",
                   fq, qr, kTextDim);
        }

        const wchar_t* const bl[2] = { L"保存", L"跳过" };
        for (int i = 0; i < 2; ++i) {
            Gdiplus::Rect r = CardNoteBtnRect(i);
            bool hot = (a.ui.hover == CardBtnHit(i));
            ARGB fill = (i == 0) ? (hot ? kCardHot : kCard) : kLocked;
            RR(g, r, 10, fill, kAccent, hot ? 2.0f : 1.2f);
            Gdiplus::Font f(L"Microsoft YaHei", 16);
            Center(g, bl[i], f, r, kText);
        }
        return;
    }

    // ---- 三个类别 Tab
    for (int i = 0; i < 3; ++i) {
        bool on = (a.ui.assetKind == i);
        bool hot = (a.ui.hover == CardTabHit(i));
        Gdiplus::Rect r = CardTabRect(i);
        ARGB fill = on ? kCardHot : (hot ? Color::MakeARGB(255, 52, 44, 68) : kCard);
        RR(g, r, 9, fill, on ? kAccent : Color::MakeARGB(120, 90, 90, 110), on ? 2.2f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, CardKindLabel(i), f, r, on ? kText : kTextDim);
    }
    // ---- 孤儿注解提醒（画在类别 Tab 右侧的空白区，不占网格）
    //
    // 只提醒、不动手真删要等"再进一次素材页"（见 GoScreen 里的 orphanArmed）。
    // 这一次机会是给人去补图的：看到提示就知道目录里还缺哪张图。
    //
    // 为什么要列名字改名错误唯一能暴露的地方就是这里。
    // 「设定里的名字的房间」打成「楼史的房间」，注解立刻变孤儿，而且不报错
    // 她只是再也不去那个地方。名字出现在这一行，才知道该去改文件名。
    if (!a.ui.orphanNames.empty()) {
        Gdiplus::Font fo(L"Microsoft YaHei", 13);
        std::wstring cnt = WFromInt((long long)a.ui.orphanNames.size());
        Gdiplus::Rect r1(660, 94, 530, 22);
        Center(g, L"检测到 " + cnt + L" 条注解没有对应素材，下次打开素材页将被清除",
               fo, r1, Color::MakeARGB(255, 235, 175, 95));
        std::wstring list;
        for (size_t i = 0; i < a.ui.orphanNames.size(); ++i) {
            if (i) list += L"、";
            list += a.ui.orphanNames[i];
        }
        if (list.size() > 38) list = list.substr(0, 37) + L"…";
        Gdiplus::Rect r2(660, 118, 530, 20);
        Center(g, list, fo, r2, Color::MakeARGB(255, 200, 145, 90));
    }
    // ---- 操作按钮
    //
    // 为什么只有三个
    // 原来还有第 4 个「清孤儿」，是给"图在资源管理器里删了、注解还留着"
    // 留的手动出口。现在 CardRefresh 会自动把没有对应素材的注解全清掉
    // （不管值是不是空的），所以打开素材页之后孤儿必然是 0 条，
    // 第 4 个按钮永远灰着——留着就是个点了没反应还没解释的坑。
    const wchar_t* const bl[3] = { L"＋ 导入", L"删除", L"写注释" };
    for (int i = 0; i < 3; ++i) {
        Gdiplus::Rect r = CardBtnRect(i);
        bool hot = (a.ui.hover == CardBtnHit(i));
        bool disabled = (i >= 1 && i <= 2 && a.ui.assetPick < 0);
        ARGB fill = disabled ? kLocked : (hot ? kCardHot : kCard);
        if (i == 1 && a.ui.assetConfirmDel) fill = Color::MakeARGB(255, 150, 50, 60);
        RR(g, r, 10, fill, disabled ? Color::MakeARGB(120, 90, 90, 110) : kAccent, 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        std::wstring label = bl[i];
        if (i == 1 && a.ui.assetConfirmDel) label = L"确认删除？";
        Center(g, label, f, r, kText);
    }

    // ---- 编辑人设 / 头像
    {
        Gdiplus::Rect r = CardAvatarBtnRect();
        bool hot = (a.ui.hover == CardAvatarBtnHit());
        RR(g, r, 10, hot ? kCardHot : kCard, kAccent, 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Center(g, L"头像", f, r, kText);
    }
    {
        Gdiplus::Rect r = CardPersonaBtnRect();
        bool hot = (a.ui.hover == CardPersonaBtnHit());
        RR(g, r, 10, hot ? kCardHot : kCard, kAccent, 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Center(g, L"编辑人设", f, r, kText);
    }

    // ---- 网格
    int perPage = kAsCols * kAsRows;
    int start = a.ui.scroll * perPage;
    if (a.ui.assetNames.empty()) {
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Gdiplus::Rect r(200, 320, 880, 50);
        Center(g, L"（这一类还没有素材——点「导入」加进来）", f, r, kTextDim);
        return;
    }

    for (int i = 0; i < perPage; ++i) {
        int idx = start + i;
        if (idx >= (int)a.ui.assetNames.size()) break;
        const std::wstring& name = a.ui.assetNames[idx];
        Gdiplus::Rect r = CardGridRect(i);
        bool picked = (a.ui.assetPick == idx);
        bool hot = (a.ui.hover == idx);
        RR(g, r, 12, (picked || hot) ? kCardHot : kCard,
           picked ? kAccent : Color::MakeARGB(120, 90, 90, 110), picked ? 2.5f : 1.2f);

        // 图片类画缩略图，音乐画一个占位块（没有图可画）。
        // 用 contain（完整显示）——素材管理页是要作者辨认素材的，
        // 裁掉一半的话「惊讶」和「坏笑」根本分不出来。
        Gdiplus::Rect ir = CardThumbBox(r);
        if (a.ui.assetKind != 2) {
            Image* img = a.rend.Bg(CardThumbPath(a, name));
            if (img) {
                Gdiplus::RectF dst = FitRectInside(img, ir);
                g.SetClip(ir);
                g.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBicubic);
                g.DrawImage(img, dst);
                g.SetInterpolationMode(Gdiplus::InterpolationModeDefault);
                g.ResetClip();
            } else {
                Gdiplus::SolidBrush ph(Color::MakeARGB(80, 60, 55, 75));
                g.FillRectangle(&ph, ir);
                Gdiplus::Font fp(L"Microsoft YaHei", 12);
                Center(g, L"(读取失败)", fp, ir, kTextDim);
            }
        } else {
            Gdiplus::SolidBrush ph(Color::MakeARGB(70, 60, 55, 75));
            g.FillRectangle(&ph, ir);
            Gdiplus::Font fp(L"Microsoft YaHei", 26);
            Center(g, L"♪", fp, ir, kText);
        }
        // 名字 + 有没有注解。缺注解的标红
        // 没说明的素材模型只能瞎猜，这个状态必须一眼看得见。
        //
        // 文字列比原来窄，所以注解要按字数截断：
        // DrawCentered 不会自动裁，超长会画到格子外面去。
        Gdiplus::Rect tc = CardTextCol(r);
        Gdiplus::Rect nr(tc.X, tc.Y, tc.Width, 28);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Center(g, name, f, nr, kText);

        std::wstring note = CardNoteGet(a, name);
        Gdiplus::Rect sr(tc.X, tc.Y + 34, tc.Width, 22);
        Gdiplus::Font fs(L"Microsoft YaHei", 12);
        if (note.empty()) {
            Center(g, L"缺注解", fs, sr, Color::MakeARGB(255, 230, 120, 120));
        } else {
            // 一列 12px 字最多放 14 个中文字，多出来的用省略号
            std::wstring shown = note;
            if (shown.size() > 14) shown = shown.substr(0, 13) + L"…";
            Center(g, shown, fs, sr, kTextDim);
        }
    }

    if (!a.ui.noteQueue.empty()) {
        Gdiplus::Font f(L"Microsoft YaHei", 13);
        Gdiplus::Rect r(90, kScreenH - 44, 1100, 24);
        Center(g, L"还有 " + WFromInt((long long)a.ui.noteQueue.size()) + L" 个刚导入的素材没写注解",
               f, r, Color::MakeARGB(255, 230, 120, 120));
    }
}

// 人设页
static void DrawPersona(Graphics& g, App& a) {
    DrawBackdropBack(g, a);
    const CharDef* d = CardChar(a);
    DrawTitle(g, d ? (L"人设 · " + d->DisplayName()) : L"人设", 22);

    if (!d) return;
    if (!CardWritable(a)) {
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Gdiplus::Rect r(200, 300, 880, 50);
        Center(g, L"（这个角色没有 char.ini，改不了）", f, r, kTextDim);
        return;
    }

    std::wstring ini = CardIni(a);
    const wchar_t* const caps[4] = { L"名字", L"风格标签", L"一句话简介", L"Temperature（0.1~2.0）" };
    std::wstring vals[4] = {
        IniGetStr(ini, L"Char", L"Name", L""),
        IniGetStr(ini, L"Char", L"Tag", L""),
        IniGetStr(ini, L"Char", L"Desc", L""),
        IniGetStr(ini, L"Char", L"Temperature", L"")
    };

    for (int i = 0; i < 4; ++i) {
        Gdiplus::Rect r = CardPersonaRect(i);
        bool on = (a.ui.personaRow == i);
        bool hot = (a.ui.hover == i);
        RR(g, r, 10, (on || hot) ? kCardHot : kCard,
           on ? kAccent : Color::MakeARGB(120, 90, 90, 110), on ? 2.2f : 1.2f);

        Gdiplus::Rect kr(r.X + 18, r.Y + 8, 210, r.Height - 16);
        Gdiplus::Font fk(L"Microsoft YaHei", 15);
        Center(g, caps[i], fk, kr, kTextDim);

        Gdiplus::Rect vr(r.X + 240, r.Y + 8, r.Width - 270, r.Height - 16);
        std::wstring shown = vals[i];
        if (shown.size() > 46) shown = shown.substr(0, 46) + L"…";
        Gdiplus::Font fv(L"Microsoft YaHei", 15);
        Center(g, shown.empty() ? L"（空）" : shown, fv, vr,
               shown.empty() ? kTextDim : kText);
    }

    // 保存按钮：编辑框不自动提交，写完点它才落盘
    {
        Gdiplus::Rect r = CardPersonaSaveRect();
        bool hot = (a.ui.hover == CardPersonaSaveHit());
        RR(g, r, 10, hot ? kCardHot : kCard, kAccent, hot ? 2.0f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, L"保存", f, r, kText);
    }

    // 人设全文入口：[Prompt] 段——她怎么说话 + 示例台词。
    // 大段多行文本，塞进上面四行里会挤得看不清，所以单独一页。
    {
        Gdiplus::Rect r = CardPtEntryRect();
        bool hot = (a.ui.hover == CardPtEntryHit());
        RR(g, r, 10, hot ? kCardHot : kCard, kAccent, hot ? 2.0f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, L"人设全文…", f, r, kText);
    }

    // 前世记忆入口：那段比这四行长得多（出身 / 在意的人 / 记得的小事 / 雷区），
    // 塞进这四行里会挤得看不清，所以单独一页。
    {
        Gdiplus::Rect r = CardMemEntryRect();
        bool hot = (a.ui.hover == CardMemEntryHit());
        RR(g, r, 10, hot ? kCardHot : kCard, kAccent, hot ? 2.0f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, L"前世记忆…", f, r, kText);
    }

    Gdiplus::Font fh(L"Microsoft YaHei", 13);
    Gdiplus::Rect hr(150, kScreenH - 60, 980, 26);
    Center(g, L"点一行改它，改完点「保存」写回 char.ini", fh, hr, kTextDim);
}
// ============================================================================
//   前世记忆页 —— 编辑 char.ini 的 [Memory] 段
// ============================================================================
//  这一段是"她这一世之前经历过什么"，不是人设标签：
//  标签只能生成类型化反应（被撩就脸红），具体记忆才能生成主动行为
//  （"说到这个，我小时候…"）。所以它是角色包内容，跟着包走。
//
//  界面上把它摊平成"一行一条"：出身 / 习惯是两条固定行，
//  在意.N / 记得.N / 雷区.N / 我们.N 是四条可增删的列表。
//  「我们」是两人共同经历过的事——续集设定下这一段最出戏，
//  所以也给它一个入口，别让作者只能开记事本改。
//  保存时按顺序重新编号写回——删中间一条不会留下空洞。
//  （解析时本来就会跳过空值，但编号一乱，下次打开看到的顺序就跟 ini 里
//   对不上了，排查起来很痛苦，所以还是重排干净。）
struct MemItem {
    std::wstring grp;    // 出身 / 习惯 / 在意 / 记得 / 雷区 / 我们
    std::wstring val;
    bool         fixed;  // 出身 / 习惯：不能删
};

// 组的中文名与 ini 前缀一致，直接当 ini 键用，不用再维护一张映射表。
static const wchar_t* kMemGrpCap(int g) {
    static const wchar_t* const c[6] = { L"出身与日常", L"说话的习惯", L"在意的人", L"记得的小事", L"在意的事/雷区", L"你们之间" };
    return (g >= 0 && g < 6) ? c[g] : L"";
}
static int MemGrpOf(const std::wstring& key) {
    if (key == L"出身") return 0;
    if (key == L"习惯") return 1;
    if (key == L"在意") return 2;
    if (key == L"记得") return 3;
    if (key == L"雷区") return 4;
    if (key == L"我们") return 5;
    return -1;
}

static std::vector<MemItem> CardMemLoad(const App& a) {
    std::vector<MemItem> v;
    std::wstring ini = CardIni(a);
    if (ini.empty()) return v;
    const wchar_t* const g[6] = { L"出身", L"习惯", L"在意", L"记得", L"雷区", L"我们" };
    for (int k = 0; k < 6; ++k) {
        if (k < 2) {
            MemItem it; it.grp = g[k]; it.fixed = true;
            it.val = IniGetStr(ini, L"Memory", g[k], L"");
            v.push_back(it);
        } else {
            for (int i = 1; i <= kMemMax; ++i) {
                std::wstring key = std::wstring(g[k]) + L"." + WFromInt(i);
                std::wstring val = IniGetStr(ini, L"Memory", key.c_str(), L"");
                // 跟 ParseCharMemory 保持一致：跳过空槽继续扫。
                // 否则会出现"她记得 4 条、界面只显示 3 条"这种对不上的情况。
                if (MemValEmpty(val)) continue;
                MemItem it; it.grp = g[k]; it.fixed = false; it.val = val;
                v.push_back(it);
            }
        }
    }
    // 还没落盘的新行：插到它那一组的最后，界面上按普通行处理。
    // 有了它 memRow 永远指向真实存在的行，"保存"不会静默失效。
    if (!a.ui.memDraft.empty()) {
        MemItem it; it.grp = a.ui.memDraft; it.fixed = false;
        size_t at = v.size();
        for (size_t k = v.size(); k-- > 0;) if (v[k].grp == it.grp) { at = k + 1; break; }
        v.insert(v.begin() + at, it);
    }
    return v;
}

static void CardMemSave(App& a, const std::vector<MemItem>& v) {
    std::wstring ini = CardIni(a);
    if (ini.empty()) return;
    // 先清干净：把可能出现的最大编号都写空，避免删掉末尾几条后残留。
    const wchar_t* const g[6] = { L"出身", L"习惯", L"在意", L"记得", L"雷区", L"我们" };
    for (int k = 0; k < 6; ++k) {
        if (k < 2) { IniSetStr(ini, L"Memory", g[k], L""); continue; }
        for (int i = 1; i <= kMemMax; ++i)
            IniSetStr(ini, L"Memory", (std::wstring(g[k]) + L"." + WFromInt(i)).c_str(), L"");
    }
    // 再按顺序写回，同组自动重新编号
    int n[6] = { 0, 0, 0, 0, 0, 0 };
    for (size_t i = 0; i < v.size(); ++i) {
        int gi = MemGrpOf(v[i].grp);
        if (gi < 0) continue;
        if (v[i].val.empty()) continue;       // 空行不落盘，省得留一堆空键
        if (gi < 2) { IniSetStr(ini, L"Memory", g[gi], v[i].val); continue; }
        n[gi] += 1;
        IniSetStr(ini, L"Memory", (std::wstring(g[gi]) + L"." + WFromInt(n[gi])).c_str(), v[i].val);
    }
    // 新行已经落盘，草稿态可以收了（不清的话下次载入会又多出一条空的）。
    a.ui.memDraft.clear();
    // 立刻生效：只重读这一段，不重载整个角色库
    //（重载会把白名单也推倒重来，界面上的选中态跟着丢）。
    const CharDef* d = CardChar(a);
    if (d) const_cast<CharDef*>(d)->memory = ParseCharMemory(ini);
}

// 点某行时编辑框里预填什么
static std::wstring CardMemValue(const App& a, int idx) {
    std::vector<MemItem> v = CardMemLoad(a);
    if (idx < 0 || idx >= (int)v.size()) return L"";
    return v[idx].val;
}

static void DrawCardMemory(Graphics& g, App& a) {
    DrawBackdropBack(g, a);
    const CharDef* d = CardChar(a);
    DrawTitle(g, d ? (L"前世记忆 · " + d->DisplayName()) : L"前世记忆", 22);

    if (!d) return;
    if (!CardWritable(a)) {
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Gdiplus::Rect r(200, 300, 880, 50);
        Center(g, L"（这个角色没有 char.ini，改不了）", f, r, kTextDim);
        return;
    }

    std::vector<MemItem> v = CardMemLoad(a);
    int per = kMemRowsPerPage;
    int pages = (int)((v.size() + per - 1) / per);
    if (pages < 1) pages = 1;
    if (a.ui.scroll >= pages) a.ui.scroll = pages - 1;
    if (a.ui.scroll < 0) a.ui.scroll = 0;
    int start = a.ui.scroll * per;

    for (int i = 0; i < per; ++i) {
        int idx = start + i;
        if (idx >= (int)v.size()) break;
        Gdiplus::Rect r = CardMemRowRect(i);
        bool on  = (a.ui.memRow == idx);
        bool hot = (a.ui.hover == idx);
        RR(g, r, 10, (on || hot) ? kCardHot : kCard,
           on ? kAccent : Color::MakeARGB(120, 90, 90, 110), on ? 2.2f : 1.2f);

        int gi = MemGrpOf(v[idx].grp);
        std::wstring cap = (gi >= 0 ? std::wstring(kMemGrpCap(gi)) : v[idx].grp);
        if (gi >= 2) {
            // 组内的真实序号（= 写回 ini 时的编号）。不能拿页内行号凑，
            // 翻页之后行号会从 1 重来，跟 ini 里的 记得.7 对不上。
            int seq = 0;
            for (int k = 0; k <= idx; ++k) if (v[k].grp == v[idx].grp) ++seq;
            cap += L" " + WFromInt(seq);
        }

        Gdiplus::Rect kr(r.X + 16, r.Y + 8, 190, r.Height - 16);
        Gdiplus::Font fk(L"Microsoft YaHei", 14);
        Center(g, cap, fk, kr, kTextDim);

        Gdiplus::Rect vr(r.X + 214, r.Y + 8, r.Width - 244, r.Height - 16);
        std::wstring shown = v[idx].val;
        if (shown.size() > 52) shown = shown.substr(0, 52) + L"…";
        Gdiplus::Font fv(L"Microsoft YaHei", 14);
        Center(g, shown.empty() ? L"（空）" : shown, fv, vr,
               shown.empty() ? kTextDim : kText);
    }

    const wchar_t* const bc[4] = { L"上一页", L"下一页", L"新增", L"删除" };
    for (int i = 0; i < 4; ++i) {
        Gdiplus::Rect r = CardMemBtnRect(i);
        bool grey = false;
        if (i == 0 && a.ui.scroll <= 0) grey = true;
        if (i == 1 && a.ui.scroll >= pages - 1) grey = true;
        if (i == 3 && (a.ui.memRow < 0 || (a.ui.memRow < (int)v.size() && v[a.ui.memRow].fixed))) grey = true;
        bool hot = (a.ui.hover == CardMemBtnHit(i)) && !grey;
        RR(g, r, 10, hot ? kCardHot : kCard, kAccent, hot ? 2.0f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Center(g, bc[i], f, r, grey ? kTextDim : kText);
    }
    {
        Gdiplus::Rect r = CardMemSaveRect();
        bool hot = (a.ui.hover == CardMemSaveHit());
        RR(g, r, 10, hot ? kCardHot : kCard, kAccent, hot ? 2.0f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Center(g, L"保存", f, r, kText);
    }

    Gdiplus::Font fh(L"Microsoft YaHei", 13);
    Gdiplus::Rect hr(150, kScreenH - 46, 980, 26);
    Center(g, L"点一行改它，改完点「保存」写回 char.ini　·　「新增」加在当前选中行的同一组里",
           fh, hr, kTextDim);
}

// 头像页
static void DrawAvatar(Graphics& g, App& a) {
    DrawBackdropBack(g, a);
    const CharDef* d = CardChar(a);
    DrawTitle(g, d ? (L"头像 · " + d->DisplayName()) : L"头像", 22);

    if (!d) return;

    // ---- 左：当前卡面
    Gdiplus::Rect pv = CardAvatarPreviewRect();
    RR(g, pv, 14, kCard, kAccent, 1.5f);
    Image* cur = a.rend.CharPortrait(d);
    if (cur) {
        Gdiplus::RectF dst = FitRectInside(cur, Gdiplus::Rect(pv.X + 8, pv.Y + 8, pv.Width - 16, pv.Height - 16));
        g.SetClip(pv);
        g.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBicubic);
        g.DrawImage(cur, dst);
        g.SetInterpolationMode(Gdiplus::InterpolationModeDefault);
        g.ResetClip();
    } else {
        Gdiplus::Font fp(L"Microsoft YaHei", 15);
        Center(g, L"（当前头像读不出来）", fp, pv, kTextDim);
    }
    Gdiplus::Font fc(L"Microsoft YaHei", 14);
    Center(g, L"当前头像", fc, Gdiplus::Rect(pv.X, pv.Y + pv.Height + 8, pv.Width, 26), kTextDim);
    Gdiplus::Font fs(L"Microsoft YaHei", 12);
    Center(g, L"选角卡片上显示的就是这一张",
           fs, Gdiplus::Rect(pv.X - 20, pv.Y + pv.Height + 34, pv.Width + 40, 24), kTextDim);

    if (!CardWritable(a)) {
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, L"（这个角色没有 char.ini，改不了）", f,
               Gdiplus::Rect(440, 300, 700, 50), kTextDim);
        return;
    }

    // ---- 右：候选网格
    if (a.ui.avatarPaths.empty()) {
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, L"（没找到图片——立绘目录里是空的）", f,
               Gdiplus::Rect(440, 300, 700, 50), kTextDim);
        return;
    }

    int perPage = kAvCols * kAvRows;
    int start = a.ui.scroll * perPage;
    for (int i = 0; i < perPage; ++i) {
        int idx = start + i;
        if (idx >= (int)a.ui.avatarPaths.size()) break;
        Gdiplus::Rect r = CardAvGridRect(i);
        bool picked = (a.ui.avatarPick == idx);
        bool hot = (a.ui.hover == idx);
        RR(g, r, 12, (picked || hot) ? kCardHot : kCard,
           picked ? kAccent : Color::MakeARGB(120, 90, 90, 110), picked ? 2.5f : 1.2f);

        Gdiplus::Rect ir(r.X + 10, r.Y + 10, r.Width - 20, r.Height - 46);
        Image* img = a.rend.Bg(a.ui.avatarPaths[(size_t)idx]);
        if (img) {
            Gdiplus::RectF dst = FitRectInside(img, ir);
            g.SetClip(ir);
            g.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBicubic);
            g.DrawImage(img, dst);
            g.SetInterpolationMode(Gdiplus::InterpolationModeDefault);
            g.ResetClip();
        } else {
            Gdiplus::SolidBrush ph(Color::MakeARGB(80, 60, 55, 75));
            g.FillRectangle(&ph, ir);
        }

        std::wstring nm = PathStem(a.ui.avatarPaths[(size_t)idx]);
        if (nm.size() > 15) nm = nm.substr(0, 14) + L"…";
        Gdiplus::Font fn(L"Microsoft YaHei", 12);
        Center(g, nm, fn, Gdiplus::Rect(r.X + 6, r.Y + r.Height - 34, r.Width - 12, 24), kText);
    }

    // ---- 操作按钮
    const wchar_t* const bl[2] = { L"用这张当头像", L"清除（用默认造型）" };
    for (int i = 0; i < 2; ++i) {
        Gdiplus::Rect r = CardAvBtnRect(i);
        bool disabled = (i == 0 && a.ui.avatarPick < 0);
        bool hot = (a.ui.hover == CardAvBtnHit(i));
        ARGB fill = disabled ? kLocked : (hot ? kCardHot : kCard);
        RR(g, r, 10, fill, disabled ? Color::MakeARGB(120, 90, 90, 110) : kAccent, 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Center(g, bl[i], f, r, kText);
    }

    Gdiplus::Font fh(L"Microsoft YaHei", 13);
    Center(g, L"点一张选中，再点「用这张当头像」写回 char.ini",
           fh, Gdiplus::Rect(200, kScreenH - 60, 1080, 26), kTextDim);
}
// ---------------------------------------------------------------- 命中测试
// 人设全文页 —— 编辑 char.ini 的 [Prompt] 段
//
// 两份身份设定合并成一份
// 早期版本"她怎么说话"写在包里的 prompt.txt、"她是谁"写在 char.ini，
// 两者功能高度雷同：代码上要维护两条读取路径，模型上要同时读两份
// 互相打架的性格描述，而且 txt 那份角色卡根本编辑不到。
// 合并后 [Prompt] 是唯一正源：角色卡能直接编辑，换包只搬一个文件。
//
// 多行怎么存ini 里"行首一个空格"表示上一行的续行（见 IniLoad）。
// 空行写一个空格——真·空行会被当成键之间的分隔，值会被截断。
// 0 = System（怎么说），1 = Sample（示例台词）
static std::wstring CardPromptValue(const App& a, int which) {
    std::wstring ini = CardIni(a);
    if (ini.empty()) return L"";
    return IniGetStr(ini, L"Prompt", which == 1 ? L"Sample" : L"System", L"");
}
static const wchar_t* CardPromptKey(int which) { return which == 1 ? L"Sample" : L"System"; }

static void DrawPersonaText(Graphics& g, App& a) {
    DrawBackdropBack(g, a);
    const CharDef* d = CardChar(a);
    DrawTitle(g, d ? (L"人设全文 · " + d->DisplayName()) : L"人设全文", 22);
    if (!d) return;
    if (!CardWritable(a)) {
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, L"（这个角色没有 char.ini，改不了）", f,
               Gdiplus::Rect(200, 300, 880, 50), kTextDim);
        return;
    }

    const wchar_t* tabs[2] = { L"说话方式", L"示例台词" };
    for (int i = 0; i < 2; ++i) {
        Gdiplus::Rect r = CardPtTabRect(i);
        bool on  = (a.ui.personaWhich == i);
        bool hot = (a.ui.hover == CardPtTabHit(i));
        RR(g, r, 10, (on || hot) ? kCardHot : kCard,
           on ? kAccent : Color::MakeARGB(120, 90, 90, 110), on ? 2.2f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 15);
        Center(g, tabs[i], f, r, kText);
    }

    Gdiplus::Rect box = CardPtBoxRect();
    bool editing = a.ui.personaTextEdit;
    RR(g, box, 10, editing ? kCardHot : kCard,
       editing ? kAccent : Color::MakeARGB(120, 90, 90, 110), editing ? 2.0f : 1.2f);

    // 编辑时 EDIT 控件盖在这一块上，这里不画内容；没编辑时画前若干行预览。
    if (!editing) {
        Gdiplus::StringFormat sf;
        sf.SetAlignment(Gdiplus::StringAlignmentNear);
        sf.SetLineAlignment(Gdiplus::StringAlignmentNear);
        Gdiplus::Font f(L"Microsoft YaHei", 14);
        Gdiplus::SolidBrush b(kText);

        std::wstring body = CardPromptValue(a, a.ui.personaWhich);
        std::vector<std::wstring> ln;
        SplitLines(body, ln);
        int maxLn = (box.Height - 40) / 26;
        for (int i = 0; i < (int)ln.size() && i < maxLn; ++i) {
            std::wstring s2 = ln[i];
            if (s2.size() > 60) s2 = s2.substr(0, 60) + L"…";
            Gdiplus::RectF rf((float)(box.X + 16), (float)(box.Y + 12 + i * 26),
                              (float)(box.Width - 32), 26.f);
            g.DrawString(s2.c_str(), (int)s2.size(), &f, rf, &sf, &b);
        }
        if (body.empty()) {
            Gdiplus::SolidBrush bd(kTextDim);
            Gdiplus::RectF rf((float)(box.X + 16), (float)(box.Y + 12),
                              (float)(box.Width - 32), 26.f);
            std::wstring tp = L"（空 —— 点这里写）";
            g.DrawString(tp.c_str(), (int)tp.size(), &f, rf, &sf, &bd);
        } else if ((int)ln.size() > maxLn) {
            Gdiplus::SolidBrush bd(kTextDim);
            std::wstring more = L"…（共 " + std::to_wstring(ln.size()) + L" 行，点进去看全部）";
            Gdiplus::RectF rf((float)(box.X + 16), (float)(box.Y + 12 + maxLn * 26),
                              (float)(box.Width - 32), 26.f);
            g.DrawString(more.c_str(), (int)more.size(), &f, rf, &sf, &bd);
        }
    }

    {
        Gdiplus::Rect r = CardPtSaveRect();
        bool hot = (a.ui.hover == CardPtSaveHit());
        RR(g, r, 10, hot ? kCardHot : kCard, kAccent, hot ? 2.0f : 1.2f);
        Gdiplus::Font f(L"Microsoft YaHei", 16);
        Center(g, L"保存", f, r, kText);
    }

    Gdiplus::Font fh(L"Microsoft YaHei", 13);
    Center(g, L"点上面的框改，改完点「保存」写回 char.ini（续行在 ini 里是行首一个空格）",
           fh, Gdiplus::Rect(150, kScreenH - 60, 980, 26), kTextDim);
}

static int CardHitTest(const App& a, int x, int y) {
    auto inRect = [&](const Gdiplus::Rect& r) {
        return x >= r.X && x < r.X + r.Width && y >= r.Y && y < r.Y + r.Height;
    };

    if (a.ui.screen == Screen::CharCard) {
        if (inRect(CardBackRect())) return CardBackHit();
        // 命名态：面板盖住网格，只认框和两个按钮。
        // 点面板以外的地方也返回"取消"——命名这一步没有任何破坏性副作用，
        // 让它退出得越容易越好（Esc 也走同一条路）。
        if (a.ui.newCharName) {
            for (int i = 0; i < 2; ++i)
                if (inRect(ChCardNameBtnRect(i))) return ChCardNameBtnHit(i);
            if (inRect(ChCardNameBoxRect())) return ChCardNameBoxHit();
            return ChCardNameBtnHit(1);             // 别处 = 取消
        }
        // 按钮盖在卡片上方，先测按钮——否则点按钮时若正好压在某张卡上，
        // 命中的是卡（正数）而不是按钮（负数）。
        for (int i = 0; i < kChCardBtnCount; ++i) {
            if (!inRect(ChCardBtnRect(i))) continue;
            if (ChCardBtnDisabled(a, i)) continue;  // 灰掉的不响应
            return ChCardBtnHit(i);
        }
        std::vector<const CharDef*> sel = a.ui.cardShowUnbound ? a.chars.Unbound()
                                                              : a.chars.Selectable();
        int perPage = kCdCols * kCdRowsVis;
        int start = a.ui.scroll * perPage;
        for (int i = 0; i < perPage; ++i) {
            int idx = start + i;
            if (idx >= (int)sel.size()) break;
            if (inRect(CardItemRect(i))) return idx;
        }
        return -1;
    }

    if (a.ui.screen == Screen::AssetLib) {
        if (a.ui.noteEdit) {
            for (int i = 0; i < 2; ++i)
                if (inRect(CardNoteBtnRect(i))) return CardBtnHit(i);   // -3 保存 / -4 跳过
            return -1;
        }
        if (inRect(CardBackRect())) return CardBackHit();
        for (int i = 0; i < 3; ++i)
            if (inRect(CardTabRect(i))) return CardTabHit(i);
        for (int i = 0; i < 3; ++i) {
            if (!inRect(CardBtnRect(i))) continue;
            if (i >= 1 && a.ui.assetPick < 0) continue;   // 灰掉的不响应
            return CardBtnHit(i);
        }
        if (inRect(CardPersonaBtnRect())) return CardPersonaBtnHit();
        if (inRect(CardAvatarBtnRect())) return CardAvatarBtnHit();
        {
            int perPage = kAsCols * kAsRows;
            int start = a.ui.scroll * perPage;
            for (int i = 0; i < perPage; ++i) {
                int idx = start + i;
                if (idx >= (int)a.ui.assetNames.size()) break;
                if (inRect(CardGridRect(i))) return idx;
            }
        }
        return -1;
    }

    if (a.ui.screen == Screen::Avatar) {
        if (inRect(CardBackRect())) return CardBackHit();
        for (int i = 0; i < 2; ++i) {
            if (!inRect(CardAvBtnRect(i))) continue;
            if (i == 0 && a.ui.avatarPick < 0) continue;      // 灰掉的不响应
            return CardAvBtnHit(i);
        }
        {
            int perPage = kAvCols * kAvRows;
            int start = a.ui.scroll * perPage;
            for (int i = 0; i < perPage; ++i) {
                int idx = start + i;
                if (idx >= (int)a.ui.avatarPaths.size()) break;
                if (inRect(CardAvGridRect(i))) return idx;
            }
        }
        return -1;
    }

    if (a.ui.screen == Screen::Persona) {
        if (inRect(CardBackRect())) return CardBackHit();
        if (inRect(CardPersonaSaveRect())) return CardPersonaSaveHit();
        if (inRect(CardPtEntryRect()))     return CardPtEntryHit();
        if (inRect(CardMemEntryRect()))    return CardMemEntryHit();
        for (int i = 0; i < 4; ++i)
            if (inRect(CardPersonaRect(i))) return i;
        return -1;
    }

    if (a.ui.screen == Screen::Memory) {
        if (inRect(CardBackRect())) return CardBackHit();
        for (int i = 0; i < 4; ++i)
            if (inRect(CardMemBtnRect(i))) return CardMemBtnHit(i);
        if (inRect(CardMemSaveRect())) return CardMemSaveHit();
        {
            int n = (int)CardMemLoad(a).size();     // 只 load 一次：鼠标每动一下都会进这里
            int start = a.ui.scroll * kMemRowsPerPage;
            for (int i = 0; i < kMemRowsPerPage; ++i) {
                int idx = start + i;
                if (idx >= n) break;
                if (inRect(CardMemRowRect(i))) return idx;
            }
        }
        return -1;
    }

    if (a.ui.screen == Screen::PersonaText) {
        if (inRect(CardBackRect())) return CardBackHit();
        for (int i = 0; i < 2; ++i)
            if (inRect(CardPtTabRect(i))) return CardPtTabHit(i);
        if (inRect(CardPtSaveRect())) return CardPtSaveHit();
        if (inRect(CardPtBoxRect()))   return CardPtBoxHit();
        return -1;
    }
    return -1;
}
// 把 EDIT 控件摆到注释框上并聚焦。
//
// 为什么不用"点行就提交"那套
// 编辑框由窗口过程管理，这里只负责定位和取值；
// 提交时机明确放在"保存"按钮上，比靠失焦提交更不容易丢内容。
static void CardStartNote(App& a) {
    a.ui.noteEdit = true;
    if (!a.hEdit) return;
    int ex = 0, ey = 0, ew = 0, eh = 0;
    if (UiEditRowRect(a, ex, ey, ew, eh)) {
        a.rend.LogicToClient(ex, ey, ew, eh);
        SetWindowTextW(a.hEdit, CardNoteGet(a, a.ui.noteName).c_str());
        MoveWindow(a.hEdit, ex, ey, ew, eh, TRUE);
        UpdateEditFont(false);
        ShowWindow(a.hEdit, SW_SHOW);
        SetFocus(a.hEdit);
        SendMessageW(a.hEdit, EM_SETSEL, 0, -1);
    }
}

static void CardStartPersonaText(App& a) {
    a.ui.personaTextEdit = true;
    if (!a.hEdit) return;
    int ex = 0, ey = 0, ew = 0, eh = 0;
    if (UiEditRowRect(a, ex, ey, ew, eh)) {
        a.rend.LogicToClient(ex, ey, ew, eh);
        SetWindowTextW(a.hEdit, CardPromptValue(a, a.ui.personaWhich).c_str());
        MoveWindow(a.hEdit, ex, ey, ew, eh, TRUE);
        UpdateEditFont(false);
        ShowWindow(a.hEdit, SW_SHOW);
        SetFocus(a.hEdit);
        SendMessageW(a.hEdit, EM_SETSEL, 0, -1);
    }
}
// 把队列里的下一个素材推进注释编辑；队列空了就退回网格。
//
// 队列里可能有导入失败的名字（CopyFile 没成功但已经 push 了），
// 所以逐个核对清单，不在清单里的直接丢掉
// 否则会弹出一个"给根本不存在的素材写注解"的框。
static void CardNextNote(App& a) {
    a.ui.noteEdit = false;
    a.ui.noteName.clear();
    if (a.hEdit) ShowWindow(a.hEdit, SW_HIDE);

    while (!a.ui.noteQueue.empty()) {
        std::wstring n = a.ui.noteQueue.front();
        a.ui.noteQueue.erase(a.ui.noteQueue.begin());
        if (std::find(a.ui.assetNames.begin(), a.ui.assetNames.end(), n) == a.ui.assetNames.end())
            continue;
        a.ui.noteName = n;
        CardStartNote(a);
        return;
    }
}

// 人设页四行对应的 ini 键与当前值
static const wchar_t* CardPersonaKey(int i) {
    static const wchar_t* const k[4] = { L"Name", L"Tag", L"Desc", L"Temperature" };
    return (i >= 0 && i < 4) ? k[i] : L"";
}

static std::wstring CardPersonaValue(const App& a, int i) {
    std::wstring ini = CardIni(a);
    if (ini.empty() || i < 0 || i >= 4) return L"";
    return IniGetStr(ini, L"Char", CardPersonaKey(i), L"");
}
// 头像页 —— 挑一张图当卡面
// 为什么单独一页，不放进素材页
// 卡面和立绘是两码事：立绘是模型每轮在挑的表情，卡面只是选角卡片上那张脸。
// 混进素材页的话，它会出现在"模型可选清单"旁边，作者很容易顺手给它写情绪注解，
// 而模型根本不会拿它当表情——注释写了白写，还多一个没说明的素材。
//
// 候选图从哪来
// 立绘目录（含服装子目录）+ 角色包根目录里的所有图片。不读配置、不猜名字：
// 画了、放进去了，就能在这里选。
static void CardAvatarRefresh(App& a) {
    a.ui.avatarPaths.clear();
    a.ui.avatarPick = -1;
    const CharDef* d = CardChar(a);
    if (!d) return;

    std::vector<std::wstring> dirs;
    if (!d->spriteDir.empty()) {
        dirs.push_back(d->spriteDir);
        // 服装子目录写法：sprite\校服\害羞.png
        std::vector<std::wstring> subs = ListDirs(d->spriteDir);
        dirs.insert(dirs.end(), subs.begin(), subs.end());
    }
    if (!d->packDir.empty()) dirs.push_back(d->packDir);

    const wchar_t* const* ex = CardExts(0);
    for (size_t di = 0; di < dirs.size(); ++di) {
        for (int e = 0; ex[e]; ++e) {
            std::vector<std::wstring> files = ListFiles(dirs[di], ex[e]);
            for (size_t i = 0; i < files.size(); ++i) {
                // 【存"不含扩展名的完整路径"】
                // Renderer::Bg / GetImage 要的是 pathNoExt，它会自己补 .png；
                // 带扩展名传进去就变成 "a.png.png"，永远读不出来。
                // 而 PathStem 会把目录也切掉（它只返回文件名），所以这里自己剥。
                std::wstring p = files[i];
                size_t dot = p.rfind(L'.');
                if (dot != std::wstring::npos) {
                    size_t sl = p.find_last_of(L"\\/");
                    if (dot > ((sl == std::wstring::npos) ? 0 : sl)) p.erase(dot);
                }
                if (std::find(a.ui.avatarPaths.begin(), a.ui.avatarPaths.end(), p)
                    != a.ui.avatarPaths.end()) continue;
                a.ui.avatarPaths.push_back(p);
            }
        }
    }
    std::sort(a.ui.avatarPaths.begin(), a.ui.avatarPaths.end());
    a.rend.ClearCache();
}

// 存进 ini 的路径：包内写相对路径（包才搬得动），散装的写绝对路径。
static std::wstring CardAvatarIniValue(const App& a, const std::wstring& full) {
    const CharDef* d = CardChar(a);
    if (!d || d->packDir.empty()) return full;
    std::wstring pre = d->packDir;
    while (!pre.empty() && (pre[pre.size() - 1] == L'\\' || pre[pre.size() - 1] == L'/'))
        pre.erase(pre.size() - 1);
    if (full.size() > pre.size() && ToLower(full.substr(0, pre.size())) == ToLower(pre)) {
        std::wstring rel = full.substr(pre.size());
        while (!rel.empty() && (rel[0] == L'\\' || rel[0] == L'/')) rel.erase(rel.begin());
        return rel;
    }
    return full;                    // 不在包里（比如桌面上挑的图）就存绝对路径
}

static bool CardAvatarApply(App& a) {
    if (!CardWritable(a)) return false;
    if (a.ui.avatarPick < 0 || a.ui.avatarPick >= (int)a.ui.avatarPaths.size()) return false;
    std::wstring val = CardAvatarIniValue(a, a.ui.avatarPaths[(size_t)a.ui.avatarPick]);
    IniSetStr(CardIni(a), L"Sprite", L"Card", val);
    // 旧的 Portrait 键也要清掉：它优先级比 Card 低，但只要 Card 被清空就会复活，
    // 玩家会看到"明明清了配置，头像又变回去了"。
    IniSetStr(CardIni(a), L"Sprite", L"Portrait", L"");

    // 内存里那份也要改，否则要重启才看得到新头像
    CharDef* d = const_cast<CharDef*>(CardChar(a));
    if (d) d->portrait = PathJoin(d->packDir, val);   // 散装的 packDir 为空，PathJoin 直接返回 val
    a.rend.ClearCache();
    return true;
}

static bool CardAvatarClear(App& a) {
    if (!CardWritable(a)) return false;
    IniSetStr(CardIni(a), L"Sprite", L"Card", L"");
    IniSetStr(CardIni(a), L"Sprite", L"Portrait", L"");
    CharDef* d = const_cast<CharDef*>(CardChar(a));
    if (d) d->portrait.clear();     // 留空 = 走"默认造型"那条路
    a.ui.avatarPick = -1;
    a.rend.ClearCache();
    return true;
}

bool UiEditRowRect(const App& a, int& x, int& y, int& w, int& h) {
    // 角色卡页：新建角色的命名框
    if (a.ui.screen == Screen::CharCard && a.ui.newCharName) {
        Gdiplus::Rect r = ChCardNameBoxRect();
        x = r.X + 10; y = r.Y + 10; w = r.Width - 20; h = r.Height - 20;
        return true;
    }
    // 注释编辑框：跟素材页的面板对齐
    if (a.ui.screen == Screen::AssetLib && a.ui.noteEdit) {
        Gdiplus::Rect r = CardNoteBoxRect();
        x = r.X + 10; y = r.Y + 10; w = r.Width - 20; h = r.Height - 20;
        return true;
    }
    // 人设页：输入框落在被编辑那行的值区
    if (a.ui.screen == Screen::Persona && a.ui.personaRow >= 0 && a.ui.personaRow < 4) {
        Gdiplus::Rect r = CardPersonaRect(a.ui.personaRow);
        x = r.X + 240; y = r.Y + 10; w = r.Width - 270; h = r.Height - 20;
        return true;
    }
    // 人设全文页：整块编辑区就是一个输入框（内容是多行文本）
    if (a.ui.screen == Screen::PersonaText && a.ui.personaTextEdit) {
        Gdiplus::Rect r = CardPtBoxRect();
        x = r.X + 10; y = r.Y + 10; w = r.Width - 20; h = r.Height - 20;
        return true;
    }
    // 前世记忆页：同上，只是行号是"整个列表的序号"，要减去本页起始
    if (a.ui.screen == Screen::Memory && a.ui.memRow >= 0) {
        int i = a.ui.memRow - a.ui.scroll * kMemRowsPerPage;
        if (i >= 0 && i < kMemRowsPerPage) {
            Gdiplus::Rect r = CardMemRowRect(i);
            x = r.X + 214; y = r.Y + 10; w = r.Width - 244; h = r.Height - 20;
            return true;
        }
        return false;
    }
    // 剧本编辑页：右栏字段行的值那一半。行号要减掉右栏自己的滚动
    // （左栏翻页用的是 a.ui.scroll，两栏各滚各的）。
    if (a.ui.screen == Screen::SyllabusEdit && a.ui.sylEdRow >= 0) {
        int i = a.ui.sylEdRow - a.ui.sylEdFdScroll * kSylEdFdRows;
        if (i >= 0 && i < kSylEdFdRows) {
            Gdiplus::Rect r = SylEdFdRect(i);
            x = r.X + 178; y = r.Y + 8; w = r.Width - 200; h = r.Height - 16;
            return true;
        }
        return false;
    }
    if (a.ui.screen != Screen::Settings || a.ui.editingRow < 0 || a.ui.editingRow >= kSetTextRows) return false;
    Gdiplus::Rect r = SetRowRect(a.ui.editingRow);
    x = r.X + 240; y = r.Y + 6; w = r.Width - 270; h = r.Height - 12;
    return true;
}

std::wstring UiEditValue(const App& a, int row) {
    // 角色卡那两处编辑用的是同一个 EDIT 控件，取值口径必须一致，
    // 否则会出现"界面显示 A、编辑框里预填的却是 B"。
    // 命名框的占位名跟 ChCardStartName 里预填的那个保持一致。
    if (a.ui.screen == Screen::CharCard && a.ui.newCharName) return L"新角色";
    if (a.ui.screen == Screen::AssetLib && a.ui.noteEdit)
        return CardNoteGet(a, a.ui.noteName);
    if (a.ui.screen == Screen::Persona)
        return CardPersonaValue(a, a.ui.personaRow);
    if (a.ui.screen == Screen::Memory)
        return CardMemValue(a, a.ui.memRow);
    if (a.ui.screen == Screen::PersonaText)
        return CardPromptValue(a, a.ui.personaWhich);
    if (a.ui.screen == Screen::SyllabusEdit) {
        std::vector<SylEdField> v = SylEdFields(a);
        if (a.ui.sylEdRow >= 0 && a.ui.sylEdRow < (int)v.size())
            return v[(size_t)a.ui.sylEdRow].val;
        return L"";
    }
    switch (row) {
    case 0: return a.llm.baseUrl;
    case 1: return a.llm.model;
    case 2: return a.llm.apiKey;
    }
    return L"";
}

void UiCommitEdit(App& a, const std::wstring& text) {
    std::wstring t = Trim(text);
    switch (a.ui.editingRow) {
    case 0: a.llm.baseUrl = t; break;
    case 1: if (!t.empty()) a.llm.model = t; break;
    case 2: a.llm.apiKey = t; break;      // 允许清空，用来取消联网
    default: break;
    }
    SaveConfig();
}
// —— 以下到文件末尾是窗口过程、入口与各子界面的接线
// 模块：程序入口与窗口过程
#pragma comment(lib, "shell32.lib")
#pragma comment(lib, "user32.lib")      // 窗口 / 菜单 / 托盘
#pragma comment(lib, "gdi32.lib")       // CreateFontW / CreateSolidBrush / StretchBlt
#pragma comment(lib, "ole32.lib")       // 拖放（DragQueryFile 走 OLE）
#pragma comment(lib, "advapi32.lib")
#pragma comment(lib, "xaudio2.lib")

#define WM_APP_INPUT_SEND (WM_APP + 4)     // 自由输入框里按了回车
// WM_APP + 7 已废弃：
// 该机制已按要求移除，编号留空不再复用——别拿它去接别的消息，
// 免得旧版本残留的消息号被新逻辑误接。
//
// ---- 素材打回重填：她填错了就让模型自己重填
//
// 这是"不再堆匹配算法"的关键一步
// 她填的名字对不上清单时，与其在程序里猜"她大概想说害羞"，
// 不如把错的地方摆给她、让她从清单里重选一个。
// 她知道这句话是什么情绪，引擎只能从字面猜。
#define WM_APP_STAGE_FIX  (WM_APP + 8)
#define WM_APP_ASSET_NOTE (WM_APP + 9)   // 素材笔记 / 章末素材复盘 生成完毕
#define WM_APP_RUN_CODE   (WM_APP + 5)     // 代码框里按了 F5
#define WM_APP_SET_EDIT   (WM_APP + 6)     // 设置面板的文本行按了回车，提交编辑
#define IDT_FRAME         1

App g_app;
static ULONG_PTR g_gdiToken = 0;
static HICON     g_trayIcon = nullptr;
static NOTIFYICONDATAW g_nid{};
static bool      g_trayAdded = false;

// 工作线程写、主线程读的结果缓冲
static std::wstring g_chatFull;
static bool         g_chatOk = false;
static std::wstring g_chatErr;
// ★ 本次回复的结束原因（"stop" 说完了 / "length" 被输出上限掐断 / 空 = 没给）。
//
// 它唯一的作用是把"她的话太长被掐断"和"流式中途断网"分开
// 这两种都会让台词停在半句上，但修法完全不同：
// length → 让她下一轮说短一点（重发还是会断在同一个地方）
// 中途断网 → 自动重发一次（大概率能拿到完整的）
// 混在一起就只能给玩家一句笼统的提示，他照着做却解决不了问题。
static std::wstring g_chatFinishReason;
// ★ 下面这一组是主线程和 StageFix 工作线程共用的搬运槽。
// 工作线程写、主线程在 WM_APP_STAGE_FIX 里读并清空；多个线程还能同时在飞。
// wstring 并发读写是未定义行为，PostMessage 也不是 C++ 内存模型的同步原语，
// 所以每一处读写都必须持 g_app.cs。锁内只做赋值，绝不包住网络请求或绘制。
struct CsLock {
    CRITICAL_SECTION* c;
    explicit CsLock(CRITICAL_SECTION* p) : c(p) { EnterCriticalSection(c); }
    ~CsLock() { LeaveCriticalSection(c); }
    CsLock(const CsLock&) = delete;
    CsLock& operator=(const CsLock&) = delete;
};

// 素材打回的结果（工作线程 -> 主线程的搬运槽）
static std::wstring g_stageFixPose, g_stageFixBg, g_stageFixBgm, g_stageFixPose2;
//
// 日常段重写台词的搬运槽 + 模式标记。
//
// 跟上面四个的区别：那四个是素材名（要过清单校验），
// 这个是一整句台词（直接替换 she said 的那句）。
// 两种请求共用同一个线程和消息，靠这个标记区分回来后该干什么。
static std::wstring g_stageFixSay;
static bool        g_stageFixIsRewrite = false;
//
// 这一次 StageFix 请求是挑素材还是打回重填。
//
// 两者走同一条线程和同一条消息，但语义完全不同：
// 挑素材 = 每轮都发，三项全要，台词已经显示（画面后到）
// 打回 = 只在填错时发，只补错的那几项，台词挂起等它一起出
// 不区分的话，挑素材失败时会被当成"打回失败"去走引擎兜底换脸
// 而那正是明确要求去掉的行为：换脸只能由模型决定。
static bool g_stageFixIsPick = false;
//
// ---- 这一次请求是"网络失败"还是"她没给值"
//
// 这是素材日志整轮消失的成因
// 挑素材请求失败（网络不可达）时，线程投回来的是三个空串，
// 主线程那边跟"她给了但没接住""她压根没填"长得一模一样
// 三种情况都走 `fp/fb/fm 全空` 那一支，直接 return，
// 于是这一轮在素材调用运行时连一行都没有。
// 运行时 第1轮 之后直接跳到 第3轮，看起来像"她没选"或"程序拒了"，
// 实际是请求压根没发出去。
//
// 分开记，日志上才看得出来到底是网络问题还是模型问题。
static bool g_stageFixNetFail = false;
//
// ---- 挑素材失败之后发起的那次打回
//
// 这是日志标签被写错的成因
// 挑素材没接住时会置 g_stageFixIsPick=true 再发起打回（为了保住
// "不许引擎兜底换脸"这条）。可那个标志回来时又被读走当标签用，
// 于是打回重填的结果在运行时被标成（挑素材）。
//
// 后果是分不清哪次是"她填错了"——挑素材是每轮都有的正常流程，
// 打回才是异常。两者混在一起，日志上看不出问题有多严重。
// 所以要单独记一个：isPick 管行为（不许兜底），isRetry 管标签（记成打回）。
static bool g_stageFixIsRetry = false;
//
// ---- 挑素材自己的"本轮第 2 次"
//
// 跟 g_stageFixIsRetry 两码事：那个是"挑素材没接住之后发起的打回"，
// 管的是打回记录里的标签；这个是挑素材请求失败后原样再发一次。
// 混用会出事：重试那一笔会被当成一次全新的挑素材失败，
// 素材调用运行时就出现两行一模一样的"第N轮 请求失败"，
// 看着像失败了两轮，其实是同一轮发了两次。
static bool g_stageFixIsPickRetry = false;
//
// ---- 请求失败的原始原因
//
// r.err 早期版本只进 AppLog（状态栏 / 调试输出），不落盘。
// 于是运行时只剩一句"请求失败"，至于是超时、限流还是连不上，
// 事后无从判断——只能靠猜，猜错就把人往 prompt 上引。
static std::wstring g_stageFixErr;
// HTTP 状态码。429（限流）跟 500（服务端炸）的修法完全不同：
// 429 要【等一会儿再发】，立刻重发必然还是 429。
static int          g_stageFixHttpStatus = 0;
// 主对话那条流的回复是不是半截的（见 LlmResult::partial）。
// 上一次 API 请求【结束】的时刻（GetTickCount64）。
// 用来在两条请求之间垫一点间隔——见 ApiThrottle。
// ★ 两个后台线程都会读它、也都会写它（ChatThread / StageFixThread）。
// volatile 不是线程同步：C++ 内存模型下并发读写仍是未定义行为。
static std::atomic<long long> g_lastApiEndMs{0};
static std::wstring g_statusText;
static int          g_statusTimer = 0;      // 帧数，到 0 自动清空

// ★ 状态栏是跨线程可见的：后台线程会调 AppLog，主线程每帧读它。
// 所有读写收口到下面四个函数；csInit 为 false 时（锁还没建好，或已销毁）
// 走无锁路径——那两段只有主线程在跑。
static void StatusSet(const std::wstring& s, int frames) {
    if (g_app.csInit) EnterCriticalSection(&g_app.cs);
    g_statusText = s;
    g_statusTimer = frames;
    if (g_app.csInit) LeaveCriticalSection(&g_app.cs);
}
static void StatusClear() { StatusSet(L"", 0); }
static std::wstring StatusGet() {
    if (!g_app.csInit) return g_statusText;
    EnterCriticalSection(&g_app.cs);
    std::wstring s = g_statusText;
    LeaveCriticalSection(&g_app.cs);
    return s;
}
// 每帧递减一次；返回 true 表示这一帧刚好归零。
static bool StatusTick() {
    if (g_app.csInit) EnterCriticalSection(&g_app.cs);
    bool zero = false;
    if (g_statusTimer > 0 && --g_statusTimer == 0) zero = true;
    if (g_app.csInit) LeaveCriticalSection(&g_app.cs);
    return zero;
}

